    // =========================================================================
    // R4.2: durable index snapshots (see `storage::index_snapshot` for the
    // format and the crash-correctness argument)
    // =========================================================================

    /// Directory holding `hnsw_rs` graph dumps; `None` for in-memory engines.
    pub fn hnsw_snapshot_dir(&self) -> Option<std::path::PathBuf> {
        self.db_path
            .as_ref()
            .map(|p| p.join(super::index_snapshot::HNSW_SNAPSHOT_DIR))
    }

    /// Arm the snapshot-invalidation hooks on both index managers. Called
    /// once at open, before WAL replay or any other mutation can run.
    fn wire_index_snapshot_hooks(&self) {
        let db = Arc::clone(&self.db);
        let gate = Arc::clone(&self.gate);
        self.art_index_manager.set_snapshot_invalidation_hook(Arc::new(move || {
            Self::delete_prefix_raw(&db, &gate, super::index_snapshot::ART_SNAPSHOT_MARKER_PREFIX.as_bytes());
        }));
        let db = Arc::clone(&self.db);
        let gate = Arc::clone(&self.gate);
        self.vector_indexes.set_snapshot_invalidation_hook(Arc::new(move || {
            Self::delete_prefix_raw(&db, &gate, super::index_snapshot::VEC_SNAPSHOT_MARKER_PREFIX.as_bytes());
        }));
    }

    /// Delete every key under `prefix`. Used by the invalidation hooks, which
    /// only have the raw DB handle (keys are plaintext even with encryption).
    fn delete_prefix_raw(db: &DB, gate: &WriteGate, prefix: &[u8]) {
        let mut read_opts = ReadOptions::default();
        read_opts.set_total_order_seek(true);
        let iter = db.iterator_opt(IteratorMode::From(prefix, rocksdb::Direction::Forward), read_opts);
        let mut batch = WriteBatch::default();
        for item in iter {
            let Ok((key, _)) = item else { break };
            if !key.starts_with(prefix) {
                break;
            }
            batch.delete(key);
        }
        // The first index mutation after every open fires this hook, and a
        // store that never checkpointed its index snapshots has no marker to
        // delete. Writing the empty batch anyway logged a write group with no
        // operations — a no-op that a physical standby still has to read past.
        if batch.is_empty() {
            return;
        }
        // Spec R5.3: the first index mutation after a checkpoint may be a schema
        // statement's (a new table's PRIMARY KEY tree, an index it drops). The markers
        // are derived state: deleting them changes no catalog and no row, and must not
        // wait for the statement's group, which a crash could lose after the mutation.
        let _allowed = super::ddl_batch::allow_side_write("index snapshot markers invalidated by an index mutation");
        if let Err(e) = gate.write(db, batch, None) {
            warn!("index snapshot marker invalidation failed: {}", e);
        }
    }

    /// Durably invalidate all ART snapshot markers.
    pub fn invalidate_art_snapshot_markers(&self) {
        Self::delete_prefix_raw(
            &self.db,
            &self.gate,
            super::index_snapshot::ART_SNAPSHOT_MARKER_PREFIX.as_bytes(),
        );
    }

    /// Durably invalidate all vector snapshot markers.
    pub fn invalidate_vector_snapshot_markers(&self) {
        Self::delete_prefix_raw(
            &self.db,
            &self.gate,
            super::index_snapshot::VEC_SNAPSHOT_MARKER_PREFIX.as_bytes(),
        );
    }

    /// Enable/disable snapshot persistence at clean shutdown. Crash-recovery
    /// tests disable it to simulate a process killed mid-run.
    pub fn set_index_snapshots_on_close(&self, enabled: bool) {
        self.index_snapshots_on_close.store(enabled, Ordering::Release);
    }

    /// Whether the close path should persist index snapshots.
    pub fn index_snapshots_on_close(&self) -> bool {
        self.index_snapshots_on_close.load(Ordering::Acquire)
    }

    /// Enable/disable the durable row-counter flush at clean shutdown.
    /// Crash-recovery tests disable it to simulate a process killed mid-run,
    /// mirroring `set_index_snapshots_on_close` — together the two toggles let
    /// a test construct either "crash landed between the two close-time
    /// durable writes" state without process-level kill injection.
    pub fn set_row_counter_flush_on_close(&self, enabled: bool) {
        self.row_counter_flush_on_close.store(enabled, Ordering::Release);
    }

    /// Whether the close path should flush row counters.
    pub fn row_counter_flush_on_close(&self) -> bool {
        self.row_counter_flush_on_close.load(Ordering::Acquire)
    }

    /// Stash the report of how the last open populated the indexes.
    pub(crate) fn set_last_index_open_report(&self, report: super::index_snapshot::IndexOpenReport) {
        *self.last_index_open_report.write() = Some(report);
    }

    /// How the last open populated the in-memory indexes (None before the
    /// first `rebuild_all_indexes` of this process).
    pub fn last_index_open_report(&self) -> Option<super::index_snapshot::IndexOpenReport> {
        self.last_index_open_report.read().clone()
    }

    /// Checkpoint: persist ART entries and standard HNSW graphs so the next
    /// open can skip the O(table-size) rebuild.
    ///
    /// ART: write order per table is snapshot-then-marker through the
    /// encrypting `put` path, so a crash mid-checkpoint leaves at worst a
    /// marker-less snapshot (ignored at open → scan rebuild). Should be
    /// called quiescent (the embedded close path checks for open
    /// transactions); a racing mutation is detected after the marker writes
    /// and re-invalidates them.
    ///
    /// HNSW (Sprinter 746342a0bfbb), per standard index: an index unchanged
    /// since the dump its sidecar describes keeps that dump and only gets its
    /// marker back; a changed one is dumped under a fresh basename (fsynced,
    /// renamed into `{data_dir}/hnsw_snapshots/`), its sidecar and marker are
    /// written in ONE batch, and only then is the previous dump removed. An
    /// empty graph is not dumped. With at-rest encryption on, NO graph is
    /// dumped: hnsw_rs writes plaintext files only, so those indexes rebuild
    /// from their sealed rows at open (`IndexSnapshotPersistReport::vector_skipped`).
    pub fn persist_index_snapshots(&self) -> Result<super::index_snapshot::IndexSnapshotPersistReport> {
        use super::index_snapshot as snap;

        let started = std::time::Instant::now();
        let mut report = snap::IndexSnapshotPersistReport::default();
        let Some(dump_dir) = self.hnsw_snapshot_dir() else {
            // In-memory engine: nothing survives the process anyway.
            return Ok(report);
        };
        // Every artefact below is a write, and the HNSW dumps are files in the
        // data directory: ask the gate once, before anything is touched, so a
        // handle that may not write leaves the directory as it found it.
        self.gate.check()?;

        // A prepared row group may have sampled dirty snapshot state before
        // this checkpoint. Rearming underneath it could leave another table's
        // marker valid after that group clears the global clean flag. Defer
        // before any cache write while a row owner or graph publisher is active.
        let snapshot_ticket = self.snapshot_manager.snapshot_publication_ticket();
        let schema_ticket = self.schema_generation();
        let vector_ticket = match self.vector_indexes.publication_ticket() {
            Some(ticket)
                if !self.write_census.any_uncommitted_writes() && !self.table_locks.current_statement_holds_any() =>
            {
                ticket
            }
            _ => {
                report.elapsed_ms = started.elapsed().as_secs_f64() * 1000.0;
                tracing::debug!("index snapshot checkpoint deferred while writers are active");
                return Ok(report);
            }
        };

        // Ordinary native fast writers keep their shared table owner through
        // their final ART hook, including with time travel disabled. Serialize
        // this rare maintenance path against that WHOLE operation; a snapshot
        // timestamp is not a generation for an older/out-of-order commit.
        // Acquire all names in the normal sorted order before manager/tree,
        // dictionary, stats, row or database resources. Never upgrade an outer
        // statement owner (checked above), which could already hold a later key.
        let catalog = super::Catalog::new(self);
        let tables = catalog.list_main_tables()?;
        let names: Vec<_> = tables.iter().map(String::as_str).collect();
        let _checkpoint_tables =
            self.lock_tables_exclusive(super::table_locks::MAIN_LEVEL, &names, "an index snapshot checkpoint")?;
        if self.write_census.any_uncommitted_writes()
            || !self.vector_indexes.publication_is_current(vector_ticket)
            || self.snapshot_manager.snapshot_publication_ticket() != snapshot_ticket
            || self.schema_generation() != schema_ticket
        {
            report.elapsed_ms = started.elapsed().as_secs_f64() * 1000.0;
            tracing::debug!("index snapshot checkpoint deferred after waiting for table owners");
            return Ok(report);
        }

        // Re-arm validity BEFORE exporting. A mutation racing this checkpoint
        // flips the flag (and deletes whatever markers exist); the post-write
        // check below then removes the markers written here.
        self.art_index_manager.mark_snapshot_clean();
        self.vector_indexes.mark_snapshot_clean();

        let marker = snap::SnapshotMarker::current();
        let marker_bytes = bincode::serialize(&marker).map_err(|e| Error::storage(format!("marker serialize: {e}")))?;

        for table_name in tables {
            if table_name.starts_with("helios_") {
                continue;
            }
            let indexes = self.art_index_manager.export_table_snapshot(&table_name);
            report.art_entries += indexes
                .iter()
                .map(|i| i.entries.iter().map(|(_, ids)| ids.len() as u64).sum::<u64>())
                .sum::<u64>();
            let table_snap = snap::ArtTableSnapshot {
                format_version: snap::INDEX_SNAPSHOT_FORMAT_VERSION,
                key_encoding_version: snap::ART_KEY_ENCODING_VERSION,
                indexes,
            };
            let blob =
                bincode::serialize(&table_snap).map_err(|e| Error::storage(format!("snapshot serialize: {e}")))?;
            // Snapshot first, marker second: a crash in between leaves no
            // marker and the snapshot is ignored.
            self.put(&snap::art_snapshot_key(&table_name), &blob)?;
            self.put(&snap::art_snapshot_marker_key(&table_name), &marker_bytes)?;
            report.art_tables += 1;
        }

        // Persistent backends are already durable; PQ has its own path.
        let standard: Vec<String> = self
            .vector_indexes
            .list_all_metadata()
            .into_iter()
            .filter(|m| matches!(m.index_type, super::VectorIndexType::Standard(_)))
            .map(|m| m.name)
            .collect();
        if self.is_encrypted() {
            // Sprinter 746342a0bfbb: hnsw_rs only writes plaintext files, and
            // a graph dump holds every vector; an encrypted store writes none
            // and rebuilds these indexes from their sealed rows at open.
            report.vector_skipped += standard.len() as u64;
        } else if !standard.is_empty() {
            // Basenames the current sidecars reference, so removing an index's
            // previous dump never removes one another sidecar still uses (two
            // names that sanitized alike shared one under the old scheme).
            // Unknown (a failed listing) keeps every previous dump for the sweep.
            let listing = self.meta_blobs_with_prefix(snap::VEC_SNAPSHOT_PREFIX);
            let referenced: Option<Vec<(String, String)>> = match listing {
                Ok(sidecars) => Some(
                    sidecars
                        .into_iter()
                        .filter_map(|(name, blob)| {
                            let sidecar = bincode::deserialize::<snap::VectorGraphSidecar>(&blob).ok()?;
                            Some((name, sidecar.basename))
                        })
                        .collect(),
                ),
                Err(e) => {
                    warn!(
                        "HNSW snapshot: cannot list the stored sidecars ({}); previous dumps are kept",
                        e
                    );
                    None
                }
            };
            for name in standard {
                match self.persist_vector_graph(&name, &dump_dir, &marker_bytes, referenced.as_deref()) {
                    Ok(VectorGraphCheckpoint::Dumped) => report.vector_graphs += 1,
                    Ok(VectorGraphCheckpoint::Unchanged) => report.vector_unchanged += 1,
                    Ok(VectorGraphCheckpoint::Skipped) => report.vector_skipped += 1,
                    Err(e) => {
                        warn!(
                            "HNSW snapshot dump for '{}' failed: {} — it will rebuild on open",
                            name, e
                        );
                        report.vector_dump_failures += 1;
                    }
                }
            }
        }

        // Detect both an active writer and a completed writer (census ABA).
        // Native commit publication covers ordinary ART row owners; vector
        // tickets also cover raw graph operations that have no heap census.
        let row_or_schema_changed = self.write_census.any_uncommitted_writes()
            || self.snapshot_manager.snapshot_publication_ticket() != snapshot_ticket
            || self.schema_generation() != schema_ticket;
        if row_or_schema_changed || !self.art_index_manager.snapshot_is_clean() {
            self.invalidate_art_snapshot_markers();
        }
        if row_or_schema_changed
            || !self.vector_indexes.publication_is_current(vector_ticket)
            || !self.vector_indexes.snapshot_is_clean()
        {
            self.invalidate_vector_snapshot_markers();
        }

        report.persisted = true;
        report.elapsed_ms = started.elapsed().as_secs_f64() * 1000.0;
        info!(
            "index snapshot checkpoint: {} tables ({} ART entries), HNSW {} dumped / {} kept / {} skipped, {:.1}ms",
            report.art_tables,
            report.art_entries,
            report.vector_graphs,
            report.vector_unchanged,
            report.vector_skipped,
            report.elapsed_ms
        );
        Ok(report)
    }

    /// Sprinter 746342a0bfbb: checkpoint ONE standard HNSW index (see
    /// [`Self::persist_index_snapshots`]). `referenced` holds `(index name,
    /// basename)` for every sidecar stored before this checkpoint; `None` when
    /// that is unknown, and then no previous dump is removed.
    fn persist_vector_graph(
        &self,
        name: &str,
        dump_dir: &Path,
        marker_bytes: &[u8],
        referenced: Option<&[(String, String)]>,
    ) -> Result<VectorGraphCheckpoint> {
        use super::index_snapshot as snap;
        let Some(state) = self.vector_indexes.standard_index_dump_state(name) else {
            return Ok(VectorGraphCheckpoint::Skipped);
        };
        if state == super::StandardDumpState::Empty {
            return Ok(VectorGraphCheckpoint::Skipped);
        }
        let previous = self.read_vector_sidecar(name);
        if state == super::StandardDumpState::Unchanged {
            if let Some(previous) = &previous {
                if self.vector_indexes.standard_index_matches_sidecar(name, previous)
                    && snap::graph_dump_files_present(dump_dir, &previous.basename)
                {
                    // The sidecar and its files already describe the index; the
                    // marker may have gone with another index's first mutation.
                    let marker_key = snap::vec_snapshot_marker_key(name);
                    self.write_sealed_records(&[(marker_key.as_slice(), marker_bytes)])?;
                    return Ok(VectorGraphCheckpoint::Unchanged);
                }
            }
        }

        let Some(dump) = self.vector_indexes.dump_standard_index(name, dump_dir)? else {
            return Ok(VectorGraphCheckpoint::Skipped);
        };
        let blob = bincode::serialize(&dump.sidecar).map_err(|e| Error::storage(format!("sidecar serialize: {e}")))?;
        let sidecar_key = snap::vec_snapshot_key(name);
        let marker_key = snap::vec_snapshot_marker_key(name);
        // Sidecar and marker in ONE batch: the switch to the new dump.
        let records = [
            (sidecar_key.as_slice(), blob.as_slice()),
            (marker_key.as_slice(), marker_bytes),
        ];
        if let Err(e) = self.write_sealed_records(&records) {
            if let Err(remove) = snap::remove_graph_dump(dump_dir, &dump.sidecar.basename) {
                warn!(
                    "HNSW snapshot for '{}': unreferenced dump left behind: {}",
                    name, remove
                );
            }
            return Err(e);
        }
        self.vector_indexes.mark_standard_index_dumped(name, dump.generation);

        if let Some(previous) = previous {
            let shared = referenced.is_none_or(|referenced| {
                referenced
                    .iter()
                    .any(|(other, basename)| other != name && *basename == previous.basename)
            });
            if previous.basename != dump.sidecar.basename && !shared {
                if let Err(e) = snap::remove_graph_dump(dump_dir, &previous.basename) {
                    warn!(
                        "HNSW snapshot for '{}': could not remove the previous dump '{}': {} (swept at the next open)",
                        name, previous.basename, e
                    );
                }
            }
        }
        Ok(VectorGraphCheckpoint::Dumped)
    }

    /// The decodable sidecar stored for vector index `name`, if any (marker or
    /// not).
    fn read_vector_sidecar(&self, name: &str) -> Option<super::index_snapshot::VectorGraphSidecar> {
        use super::index_snapshot as snap;
        let blob = self.get(&snap::vec_snapshot_key(name)).ok().flatten()?;
        let sidecar: snap::VectorGraphSidecar = bincode::deserialize(&blob).ok()?;
        (sidecar.index_name == name).then_some(sidecar)
    }

    /// Sprinter 746342a0bfbb: write `records` as ONE gated RocksDB batch, each
    /// value sealed exactly as [`Self::put`] seals it.
    fn write_sealed_records(&self, records: &[(&[u8], &[u8])]) -> Result<()> {
        let mut batch = WriteBatch::default();
        for &(key, value) in records {
            let stored = super::tde::seal(self.key_manager.as_deref(), value)?;
            batch.put(key, stored.as_ref());
        }
        self.gate.write(&self.db, batch, self.memory_write_options.as_ref())
    }

    /// Sprinter 746342a0bfbb: at open, delete every graph dump file in
    /// `hnsw_snapshots/` that no valid sidecar (`sidecars`, as
    /// [`Self::load_vector_sidecars`] returned them) references, and every
    /// staging directory a crashed dump left. On an encrypted store no dump is
    /// valid: every dump file goes, and so do the sidecars and markers that
    /// pointed at them. Nothing is touched by a handle that may not write.
    /// Returns how many entries were removed.
    pub(crate) fn sweep_hnsw_snapshot_dir(
        &self,
        sidecars: &std::collections::HashMap<String, super::index_snapshot::VectorGraphSidecar>,
    ) -> u64 {
        use super::index_snapshot as snap;
        if !self.gate.is_open() || self.is_physical_standby() {
            return 0;
        }
        let encrypted = self.is_encrypted();
        if encrypted {
            Self::delete_prefix_raw(&self.db, &self.gate, snap::VEC_SNAPSHOT_MARKER_PREFIX.as_bytes());
            Self::delete_prefix_raw(&self.db, &self.gate, snap::VEC_SNAPSHOT_PREFIX.as_bytes());
        }
        let Some(dir) = self.hnsw_snapshot_dir() else {
            return 0;
        };
        let keep: HashSet<&str> = if encrypted {
            HashSet::new()
        } else {
            sidecars.values().map(|sidecar| sidecar.basename.as_str()).collect()
        };
        snap::sweep_graph_dumps(&dir, &keep)
    }

    /// Remove the durable snapshot artefacts belonging to ONE vector index: the
    /// `vecsnap:` sidecar blob, its `vecsnapv:` marker, and the `hnsw_rs` graph
    /// dump files under `{data_dir}/hnsw_snapshots/`.
    ///
    /// Called by every path that removes a vector index (`DROP INDEX` and its
    /// WAL replay). Without it the artefacts are immortal: a checkpoint only
    /// ever WRITES keys for indexes that are still live, so a repeated
    /// drop/recreate cycle accumulated dead blobs and dump files with nothing
    /// to ever collect them.
    ///
    /// Correctness does not depend on this — `VectorIndexManager::drop_index`
    /// calls `note_mutation()`, whose hook durably deletes every `vecsnapv:`
    /// marker, so a stale sidecar can never be handed to the rebuild. This is
    /// purely the space leak, and it is therefore BEST EFFORT: every failure is
    /// warned by name and none of them can fail the drop that is already done.
    pub(crate) fn remove_vector_index_snapshot(&self, index_name: &str) {
        use super::index_snapshot as snap;

        // The dump basename is read back OUT of the sidecar rather than
        // re-derived: it carries a per-checkpoint generation, and sidecars
        // written before Sprinter 746342a0bfbb used the lossy sanitized index
        // name, which re-deriving could map onto a different index's files.
        if let Some(dir) = self.hnsw_snapshot_dir() {
            match self.get(&snap::vec_snapshot_key(index_name)) {
                Ok(Some(blob)) => match bincode::deserialize::<snap::VectorGraphSidecar>(&blob) {
                    Ok(sidecar) if sidecar.index_name == index_name => {
                        for suffix in [".hnsw.graph", ".hnsw.data"] {
                            let path = dir.join(format!("{}{}", sidecar.basename, suffix));
                            match std::fs::remove_file(&path) {
                                Ok(()) => {}
                                Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
                                Err(e) => warn!(
                                    "dropping vector index '{}': could not remove graph dump {:?}: {}",
                                    index_name, path, e
                                ),
                            }
                        }
                    }
                    Ok(sidecar) => warn!(
                        "dropping vector index '{}': its sidecar names index '{}' — \
                         leaving the graph dump alone",
                        index_name, sidecar.index_name
                    ),
                    Err(e) => warn!(
                        "dropping vector index '{}': sidecar is undecodable ({}) — \
                         the graph dump files are left behind",
                        index_name, e
                    ),
                },
                Ok(None) => {}
                Err(e) => warn!("dropping vector index '{}': sidecar read failed: {}", index_name, e),
            }
        }

        // Raw deletes: these keys are outside the `meta:` namespace, so going
        // through `StorageEngine::delete` would append a WAL `Delete` record
        // against a bogus table name for a checkpoint artefact.
        for key in [
            snap::vec_snapshot_key(index_name),
            snap::vec_snapshot_marker_key(index_name),
        ] {
            if let Err(e) = self.gate.delete(&self.db, &key, None) {
                warn!(
                    "dropping vector index '{}': could not remove snapshot record: {}",
                    index_name, e
                );
            }
        }
    }

    /// Read every valid ART table snapshot (marker present + versions match).
    /// Called once at the START of `rebuild_all_indexes`, before index
    /// registration consumes the markers.
    pub(crate) fn load_art_table_snapshots(
        &self,
    ) -> std::collections::HashMap<String, super::index_snapshot::ArtTableSnapshot> {
        use super::index_snapshot as snap;
        let mut out = std::collections::HashMap::new();
        for table in self.keys_with_prefix_suffixes(snap::ART_SNAPSHOT_MARKER_PREFIX) {
            let Ok(Some(marker_bytes)) = self.get(&snap::art_snapshot_marker_key(&table)) else {
                continue;
            };
            let Ok(marker) = bincode::deserialize::<snap::SnapshotMarker>(&marker_bytes) else {
                continue;
            };
            if !marker.matches_current() {
                continue;
            }
            let Ok(Some(blob)) = self.get(&snap::art_snapshot_key(&table)) else {
                continue;
            };
            let Ok(table_snap) = bincode::deserialize::<snap::ArtTableSnapshot>(&blob) else {
                warn!(
                    "ART snapshot for '{}' is unreadable — falling back to scan rebuild",
                    table
                );
                continue;
            };
            if table_snap.format_version != snap::INDEX_SNAPSHOT_FORMAT_VERSION
                || table_snap.key_encoding_version != snap::ART_KEY_ENCODING_VERSION
            {
                continue;
            }
            out.insert(table, table_snap);
        }
        out
    }

    /// Read every valid HNSW graph sidecar (marker present + versions match).
    /// None on an encrypted store (Sprinter 746342a0bfbb): a dump there can
    /// only be a plaintext one an unencrypted run left, and it is never loaded.
    pub(crate) fn load_vector_sidecars(
        &self,
    ) -> std::collections::HashMap<String, super::index_snapshot::VectorGraphSidecar> {
        use super::index_snapshot as snap;
        let mut out = std::collections::HashMap::new();
        if self.is_encrypted() {
            return out;
        }
        for index in self.keys_with_prefix_suffixes(snap::VEC_SNAPSHOT_MARKER_PREFIX) {
            let Ok(Some(marker_bytes)) = self.get(&snap::vec_snapshot_marker_key(&index)) else {
                continue;
            };
            let Ok(marker) = bincode::deserialize::<snap::SnapshotMarker>(&marker_bytes) else {
                continue;
            };
            if !marker.matches_current_format() {
                continue;
            }
            let Ok(Some(blob)) = self.get(&snap::vec_snapshot_key(&index)) else {
                continue;
            };
            let Ok(sidecar) = bincode::deserialize::<snap::VectorGraphSidecar>(&blob) else {
                warn!("HNSW sidecar for '{}' is unreadable — falling back to rebuild", index);
                continue;
            };
            out.insert(index, sidecar);
        }
        out
    }

    /// Key suffixes (after `prefix`) of every key under `prefix`.
    fn keys_with_prefix_suffixes(&self, prefix: &str) -> Vec<String> {
        let prefix_bytes = prefix.as_bytes();
        let mut read_opts = ReadOptions::default();
        read_opts.set_total_order_seek(true);
        let iter = self
            .db
            .iterator_opt(IteratorMode::From(prefix_bytes, rocksdb::Direction::Forward), read_opts);
        let mut out = Vec::new();
        for item in iter {
            let Ok((key, _)) = item else { break };
            if !key.starts_with(prefix_bytes) {
                break;
            }
            out.push(String::from_utf8_lossy(key.get(prefix_bytes.len()..).unwrap_or_default()).to_string());
        }
        out
    }

    /// Every metadata blob stored under `prefix`, as `(key suffix, value)`.
    ///
    /// Values are fetched through [`StorageEngine::get`] rather than read off
    /// the raw RocksDB iterator, because on a TDE data dir the raw iterator
    /// hands back CIPHERTEXT — `get` is the one place decryption happens. A key
    /// that disappears between the scan and the fetch is still skipped (an
    /// absent key is not an error).
    ///
    /// THIS IS THE ONE READ DISCIPLINE for prefix-scanned metadata. Do not add a
    /// second reader over `self.db.iterator_opt` that touches VALUES; it will be
    /// correct on a plaintext data dir and broken on every encrypted one.
    ///
    /// A FAILED READ PROPAGATES; it is not warned and dropped. It used to be:
    /// the downgrade existed so that a value which would not decrypt could not
    /// stop the open-time loaders, and it is exactly the silent-skip behaviour
    /// that let an entire metadata namespace vanish at open with nothing above
    /// WARN to say so. Now that `get` accepts an already-plaintext stored value
    /// (see the stored-value decode helpers), the undecryptable case does not
    /// arise here, so the only `Err` left is a genuine RocksDB read failure —
    /// which must never be swallowed.
    ///
    /// Per-RECORD resilience still belongs to the callers, and several of them
    /// keep it: `Catalog::load_all_triggers` and the routine loader warn-and-skip
    /// one undecodable blob so a single bad record cannot stop the database
    /// opening, while `Catalog::list_roles` / `list_acls` decode strictly and
    /// propagate. Whether one record is readable is a different question from
    /// whether the STORE is readable, which is what this answers.
    ///
    /// Callers: rebuilding the `FunctionRegistry` from the durable
    /// `meta:function:` / `meta:procedure:` records that
    /// `EmbeddedDatabase::execute_create_function_plan` and WAL replay
    /// (`WalOperation::CreateFunction`) both write; `Catalog::load_all_triggers`;
    /// `Catalog::load_all_trigger_row_mutations`; `Catalog::list_roles`;
    /// `Catalog::list_acls`.
    pub fn meta_blobs_with_prefix(&self, prefix: &str) -> Result<Vec<(String, Vec<u8>)>> {
        let mut out = Vec::new();
        for suffix in self.keys_with_prefix_suffixes(prefix) {
            let key = format!("{}{}", prefix, suffix).into_bytes();
            let value = self
                .get(&key)
                .map_err(|e| Error::storage(format!("failed to read metadata key '{}{}': {}", prefix, suffix, e)))?;
            if let Some(value) = value {
                out.push((suffix, value));
            }
        }
        Ok(out)
    }

    /// Complete decrypted metadata scan for immutable snapshot validation.
    /// Iterator failures, malformed names and disappearing keys are errors.
    pub fn meta_blobs_with_prefix_strict(&self, prefix: &str) -> Result<Vec<(String, Vec<u8>)>> {
        let mut options = ReadOptions::default();
        options.set_total_order_seek(true);
        let iterator = self.db.iterator_opt(
            IteratorMode::From(prefix.as_bytes(), rocksdb::Direction::Forward),
            options,
        );
        let mut output = Vec::new();
        for entry in iterator {
            let (key, _) = entry.map_err(|e| Error::storage(format!("metadata scan failed: {e}")))?;
            if !key.starts_with(prefix.as_bytes()) {
                break;
            }
            let suffix = key
                .strip_prefix(prefix.as_bytes())
                .ok_or_else(|| Error::storage("metadata key lost its prefix during scan"))?;
            let suffix = std::str::from_utf8(suffix)
                .map_err(|_| Error::storage("invalid UTF-8 metadata key"))?
                .to_owned();
            let value = self
                .get(&key.to_vec())?
                .ok_or_else(|| Error::storage("metadata disappeared during strict snapshot load"))?;
            output.push((suffix, value));
        }
        Ok(output)
    }

    /// Seed allocation state from a strict immutable image without writing it.
    pub(crate) fn reseed_row_counter_for_physical_snapshot(&self, table_name: &str, max_row_id: u64) -> Result<()> {
        if !self.open_mode.is_physical() {
            return Err(Error::storage(
                "snapshot counter hydration requires immutable snapshot mode",
            ));
        }
        let target = max_row_id
            .checked_add(1)
            .ok_or_else(|| Error::storage("row id exhausted"))?;
        let counter = self
            .row_counters
            .entry(table_name.to_owned())
            .or_insert_with(|| AtomicU64::new(0));
        counter.fetch_max(target, Ordering::Relaxed);
        Ok(())
    }

    /// Get database statistics
    pub fn get_stats(&self) -> Result<String> {
        self.db
            .property_value("rocksdb.stats")
            .map_err(|e| Error::storage(format!("Failed to get stats: {}", e)))?
            .ok_or_else(|| Error::storage("Stats not available"))
    }

    /// Check if encryption is enabled
    pub fn is_encrypted(&self) -> bool {
        self.key_manager.is_some()
    }

    /// Get encryption configuration for auditing
    pub fn encryption_info(&self) -> Option<String> {
        self.key_manager
            .as_ref()
            .map(|km| format!("Enabled (AES-256-GCM, source: {:?})", km.source()))
    }

    // --- Branch Management API ---

    /// Get the branch manager (initialized at startup)
    fn get_or_init_branch_manager(&self) -> Result<Arc<RwLock<Option<Arc<BranchManager>>>>> {
        // BranchManager is now initialized at startup, so just return it
        // This method is kept for backward compatibility
        let manager = self.branch_manager.read();
        if manager.is_none() {
            return Err(Error::storage(
                "BranchManager not initialized. Branch operations are unavailable.",
            ));
        }
        drop(manager);
        Ok(Arc::clone(&self.branch_manager))
    }

    /// Create a new branch
    ///
    /// Creates a copy-on-write branch from a parent branch (or main if not specified).
    /// The branch is created instantly with minimal overhead.
    pub fn create_branch(&self, name: &str, parent_name: Option<&str>, options: BranchOptions) -> Result<BranchId> {
        self.create_branch_at_snapshot(name, parent_name, None, options)
    }

    /// Create a branch at a specific snapshot
    ///
    /// If snapshot_id is None, the fork point is now. Otherwise the branch sees its
    /// parent, which must be main, as it was at that snapshot: the difference is
    /// materialized from version history (sprinter 6bc4a4040eb7, B4).
    pub fn create_branch_at_snapshot(
        &self,
        name: &str,
        parent_name: Option<&str>,
        snapshot_id: Option<u64>,
        options: BranchOptions,
    ) -> Result<BranchId> {
        let mgr = self
            .branch_manager()
            .ok_or_else(|| Error::storage("BranchManager not initialized. Branch operations are unavailable."))?;
        self.gate.check()?;
        let parent = parent_name.unwrap_or("main");
        let deadline = std::time::Instant::now() + super::BRANCH_DRAIN_TIMEOUT;

        // Sprinter 6bc4a4040eb7 (B4): an anchor in the past is materialized from
        // main's version history; only main has one. Pinned until the branch is
        // written: from then on it needs no history at all.
        let _anchor_pin = match snapshot_id {
            Some(anchor) => {
                if !self.config.storage.time_travel_enabled {
                    return Err(Error::query_execution(
                        "AS OF / time-travel queries require time_travel_enabled = true",
                    ));
                }
                if parent != "main" {
                    return Err(Error::branch_as_of_needs_main(name, parent));
                }
                Some(self.pin_historical_snapshot(anchor)?)
            }
            None => None,
        };

        // A branch parent is held first, so this waits out a schema statement
        // running on it (`BranchDrains::exclusive`), and that statement then
        // freezes for this child (sprinter 6bc4a4040eb7, B3 fix pass).
        let parent_meta = match mgr.get_branch_by_name(parent) {
            Ok(meta) if meta.state == super::BranchState::Active => meta,
            _ => return Err(Error::branch_not_active(parent)),
        };
        let parent_id = parent_meta.branch_id;
        let parent_is_main = parent_id == MAIN_LEVEL;
        let _parent_hold = if parent_is_main {
            super::BranchHold::none()
        } else {
            self.branch_drains.enter(parent_id, parent)?
        };
        let parent_chain: Vec<u64> = if parent_is_main {
            Vec::new()
        } else {
            self.get_branch_chain(parent_id)?
                .into_iter()
                .filter(|level| *level != MAIN_LEVEL)
                .collect()
        };
        mgr.refuse_name_in_use(name)?;
        mgr.refuse_if_in_unfinished_merge(parent_id, parent)?;

        // The id is durable before anything can be written under it: a crash from
        // here to the creation batch leaves keys of an id no branch has and none
        // will be given, which the next open reclaims.
        let branch_id = mgr.reserve_branch_id()?;
        let forked = self.fork_branch(
            &mgr,
            branch_id,
            name,
            parent_name,
            parent_id,
            &parent_chain,
            snapshot_id,
            options,
            deadline,
        );
        if forked.is_err() {
            mgr.abandon_reserved_branch(branch_id);
        }
        forked
    }

    /// Sprinter 6bc4a4040eb7 (B4): the linearization of a branch's creation, on an
    /// id no branch has yet. See `docs/plans/specs/B4_branch_fork_point.md`.
    ///
    /// 1. On main: keep new schema statements out and wait for the running ones, until
    ///    the child is registered. A statement is wholly before this fork (it finished
    ///    before the child existed) or wholly after it (it finds the child, and freezes
    ///    the definition before its first row), so the child's definition and rows come
    ///    from the same side of it.
    /// 2. Register: from here on every write of the parent freezes for the child.
    ///    Taking the registry exclusively waits for the writes that read it before.
    ///    If no level had a live child, writers were not asking at all: wait for what
    ///    is announced at the gate.
    /// 3. A merge that started in between is refused now that the hook can see it:
    ///    a resume would rewrite the parent under the child (B3).
    /// 4. The anchor's rows, if there is one.
    /// 5. The fork point, then the creation batch with the fork record. Nothing named
    ///    this branch exists before that batch, so no session can read it half filled,
    ///    and nothing that committed after this returns can show through.
    #[allow(clippy::too_many_arguments)]
    fn fork_branch(
        &self,
        mgr: &Arc<BranchManager>,
        branch_id: BranchId,
        name: &str,
        parent_name: Option<&str>,
        parent_id: BranchId,
        parent_chain: &[u64],
        anchor: Option<u64>,
        options: BranchOptions,
        deadline: std::time::Instant,
    ) -> Result<BranchId> {
        let budget = || deadline.saturating_duration_since(std::time::Instant::now());
        let parent = parent_name.unwrap_or("main");
        // The fork record still reads main's unfrozen definitions after the
        // child registers. Keep schema exclusion until that record is durable:
        // otherwise it can collect the old main epoch, then race an ALTER that
        // freezes the child's definition before its final metadata write.
        let _schema_statements = if let Some(freeze) = &self.branch_freeze {
            let statements = if parent_id == MAIN_LEVEL {
                Some(
                    freeze
                        .hold_schema_statements(budget())
                        .ok_or_else(|| Error::branch_create_busy(name, parent))?,
                )
            } else {
                // A branch parent is held by the caller, which waits out its schema
                // statement (`BranchDrains::exclusive`).
                None
            };
            // One creation at a time through its drain: a second one would see the
            // flag up and not wait for the writers this one is waiting for.
            let creating = freeze
                .creation_lock(budget())
                .ok_or_else(|| Error::branch_create_busy(name, parent))?;
            let was_active = freeze
                .register(branch_id, parent_id, budget())
                .ok_or_else(|| Error::branch_create_busy(name, parent))?;
            if !was_active && !self.gate.wait_for_unhooked_writes(deadline) {
                return Err(Error::branch_create_busy(name, parent));
            }
            drop(creating);
            statements
        } else {
            None
        };
        mgr.refuse_if_in_unfinished_merge(parent_id, parent)?;

        if let Some(anchor) = anchor {
            self.materialize_branch_anchor(branch_id, name, anchor)?;
        }

        // What the parent sees now, with what it already froze for this child in
        // the window: a table changed since is recorded as it was.
        let mut fork_chain = parent_chain.to_vec();
        fork_chain.push(branch_id);
        let forked = self.fork_entries(&fork_chain)?;
        let snapshot = anchor.unwrap_or_else(|| self.next_timestamp());
        mgr.create_reserved_branch(branch_id, name, parent_name, snapshot, options, |id, batch| {
            self.stage_branch_fork_record(id, &forked, batch)
        })
    }

    /// Drop a branch
    ///
    /// Takes it out of service, then deletes its keys in bounded batches (a crash
    /// on the way is finished by the next open). Cannot drop the main branch or
    /// branches with children.
    pub fn drop_branch(&self, name: &str, if_exists: bool) -> Result<()> {
        let manager_lock = self.get_or_init_branch_manager()?;
        let manager = manager_lock.read();
        let mgr = manager
            .as_ref()
            .ok_or_else(|| Error::storage("BranchManager not available in read lock"))?;

        // sprinter 6bc4a4040eb7 (B1): the manager bumps the registry
        // generation, so a session bound to the dropped branch re-validates on
        // its next statement and fails closed (3D000).
        mgr.drop_branch(name, if_exists)
    }

    /// Refused (2BP01) when `name` has a child branch, which a drop of it would be.
    pub(crate) fn refuse_drop_of_branch_with_child(&self, name: &str) -> Result<()> {
        let manager_lock = self.get_or_init_branch_manager()?;
        let manager = manager_lock.read();
        let mgr = manager
            .as_ref()
            .ok_or_else(|| Error::storage("BranchManager not available in read lock"))?;
        mgr.refuse_drop_of_branch_with_child(name)
    }

    /// Get branch metadata by name
    pub fn get_branch(&self, name: &str) -> Result<BranchMetadata> {
        let manager_lock = self.get_or_init_branch_manager()?;
        let manager = manager_lock.read();
        let mgr = manager
            .as_ref()
            .ok_or_else(|| Error::storage("BranchManager not available in read lock"))?;

        mgr.get_branch_by_name(name)
    }

    /// List all active branches
    pub fn list_branches(&self) -> Result<Vec<BranchMetadata>> {
        let manager_lock = self.get_or_init_branch_manager()?;
        let manager = manager_lock.read();
        let mgr = manager
            .as_ref()
            .ok_or_else(|| Error::storage("BranchManager not available in read lock"))?;

        mgr.list_branches()
    }

    /// List branches for catalog/history views: `Active` and `Merged`.
    ///
    /// Distinct from `list_branches` (Active only), which operational callers
    /// depend on. See `BranchManager::list_branches_for_catalog`.
    pub fn list_branches_for_catalog(&self) -> Result<Vec<BranchMetadata>> {
        let manager_lock = self.get_or_init_branch_manager()?;
        let manager = manager_lock.read();
        let mgr = manager
            .as_ref()
            .ok_or_else(|| Error::storage("BranchManager not available in read lock"))?;

        mgr.list_branches_for_catalog()
    }

    /// Merge a source branch into a target branch
    ///
    /// Performs a merge by copying all branch-specific data from source to target.
    /// For merging into main, data is written with the standard `data:` prefix.
    /// For merging into another branch, data is written with `bdata:` prefix.
    ///
    /// sprinter 6bc4a4040eb7 (B3 fix pass): a merge either refuses before
    /// anything changed — the source stays Active and mergeable — or it
    /// finishes. It holds every table of its plan exclusively on the target level
    /// from before its validation (spec R5.1: writers wait, and an open transaction
    /// is waited for, bounded by `[session] lock_timeout_ms` and its 30 s budget,
    /// then 55P03). Everything is validated first (the definitions and the
    /// incarnations of the target's tables, `plan_branch_merge`; PRIMARY KEY /
    /// UNIQUE on the target, `validate_merge_keys`); then a durable `MergeIntent`
    /// is written, synced; then the source is marked merged and the target
    /// changes. From there on an error leaves the intent in place:
    /// running the statement again finishes the merge, and so does the next open
    /// ([`Self::finish_pending_branch_merges`]). Every step is idempotent, the
    /// target's DDL on the merge's tables is refused (55006) until it is
    /// finished, and a DROP of either end is too.
    ///
    /// Returns MergeResult containing merge statistics.
    pub fn merge_branch(
        &self,
        source_name: &str,
        target_name: &str,
        strategy: super::MergeStrategy,
    ) -> Result<super::MergeResult> {
        self.merge_branch_inner(source_name, target_name, strategy, false, MergeFkPolicy::Enforced)
    }

    /// [`Self::merge_branch`] for a `MERGE … WITH (delete_branch_after = true)`: refused
    /// (2BP01) before anything lands if the source has a child branch, since it could
    /// not be dropped afterwards. Asked under the close of the source: a `CREATE BRANCH`
    /// from it holds its drain for the whole creation, so the close waited for that
    /// child or keeps it out, and past that nothing can be forked from a merged branch.
    pub(crate) fn merge_branch_to_drop_source(
        &self,
        source_name: &str,
        target_name: &str,
        strategy: super::MergeStrategy,
    ) -> Result<super::MergeResult> {
        self.merge_branch_inner(source_name, target_name, strategy, true, MergeFkPolicy::Enforced)
    }

    pub(crate) fn merge_branch_with_fk_policy(
        &self,
        source: &str,
        target: &str,
        strategy: super::MergeStrategy,
        source_goes_after: bool,
        policy: MergeFkPolicy,
    ) -> Result<super::MergeResult> {
        self.merge_branch_inner(source, target, strategy, source_goes_after, policy)
    }

    fn merge_branch_inner(
        &self,
        source_name: &str,
        target_name: &str,
        _strategy: super::MergeStrategy,
        source_goes_after: bool,
        requested_fk_policy: MergeFkPolicy,
    ) -> Result<super::MergeResult> {
        // sprinter 6bc4a4040eb7 (phase B3): a MERGE reads and changes catalogs
        // by explicit level — the source's own records, the target's chain,
        // main's catalog — never through the merging session's branch (it may
        // be bound to any branch). So it runs as MAIN for its duration: the
        // catalog readers answer from main's catalog, and main's catalog
        // mutators (the target-side CREATE / DROP / ADD COLUMN of a merge into
        // main) are not refused as branch writes.
        let _main_scope = crate::main_statement_scope(self.instance_id);
        // B3 second fix pass: this merge's own catalog writes are not refused as
        // DDL on the tables it holds.
        let _merge_scope = MergeDdlScope::enter(self.instance_id);
        let deadline = std::time::Instant::now() + super::BRANCH_DRAIN_TIMEOUT;
        let budget = || deadline.saturating_duration_since(std::time::Instant::now());

        let (source, target, _) = self.merge_ends(source_name, target_name, None)?;
        let source_id = source.branch_id;
        let target_id = target.branch_id;
        let merge_to_main = target_name == "main" || target_id == 1;

        // sprinter 6bc4a4040eb7 (B1 fix pass): take the source out of `Active`
        // BEFORE copying a single row — after the statements running on it have
        // finished (the drain), and while new ones are kept out. Marking it at
        // the END left the whole copy window open: a session bound to the
        // source kept writing to an overlay that had already been read, and
        // those writes were silently lost.
        let _drained = self.branch_drains.close(source_id, source_name, budget())?;
        // B1 second fix pass: what was read above may be stale — the close
        // waited for the source's running statements and possibly for a DROP
        // or MERGE that closed it first. RE-READ both ends: the source must
        // still be the branch whose drain was closed (same id) and Active (or
        // merged by the unfinished merge this statement resumes), and the
        // target likewise.
        let (source_meta, _, pending) = self.merge_ends(source_name, target_name, Some((source_id, target_id)))?;
        let fk_policy = if pending.is_some() {
            self.branch_merge_fk_policy(source_id)?
        } else {
            requested_fk_policy
        };
        if source_goes_after {
            self.refuse_drop_of_branch_with_child(source_name)?;
        }
        // B3 second fix pass: a merge of a branch another unfinished merge writes
        // into, or into a branch that is itself on its way out, could leave that
        // other merge unfinishable forever.
        if let Some(other) = self.merge_intent_in_the_way(source_id, target_id)? {
            return Err(Error::branch_merge_pending(
                &format!(
                    "branch {}",
                    if other.target_id == source_id {
                        source_name
                    } else {
                        target_name
                    }
                ),
                &other.source_name,
                &other.target_name,
            ));
        }
        // Into a branch, the merge runs on the target ALONE (B3 second fix pass,
        // every merge rather than only a schema-changing one): a statement on the
        // target checks its keys through the level's key index, and the rows land
        // on that level one by one. A DROP / MERGE of the target waits for the
        // section instead of dropping the overlay it is writing; one already
        // closing the target refuses the merge (55006). The source is closed FIRST
        // and the section gives up when the target starts closing, so two crossed
        // merges (b→c, c→b) refuse each other instead of deadlocking.
        let _target_section = if merge_to_main {
            None
        } else {
            Some(self.branch_drains.exclusive(target_id, target_name, budget())?)
        };
        // Spec R5.1: the merge holds every table of its plan exclusively, on the target
        // level, from before its key validation through the last table's landing: a
        // writer waits instead of racing it. Declared after the sections above, so it
        // lets go first; its release moves the schema generation and then runs the
        // replication wait its catalog writes deferred.
        let merge_owner = self.table_locks.separate_owner();
        let mut merge_locks = self.table_locks.exclusive_guard();
        let source_chain = self.get_branch_chain(source_id)?;
        let target_chain: Vec<u64> = if merge_to_main {
            Vec::new()
        } else {
            self.get_branch_chain(target_id)?
        };
        let ends = MergeEnds {
            deadline,
            source_name,
            target_name,
            source_id,
            target_id,
            merge_to_main,
            source_chain: &source_chain,
            target_chain: &target_chain,
        };

        let mut intent = match pending {
            Some(intent) => {
                if intent.target_id != target_id {
                    return Err(Error::branch_merge_pending(
                        &format!("branch {source_name}"),
                        source_name,
                        &intent.target_name,
                    ));
                }
                self.register_merge_intent_exclusion(&intent)?;
                // Spec R5.1: taken again, and everything validated again under it.
                let dependencies = self.merge_fk_dependency_tables(
                    source_id,
                    &target_chain,
                    &intent.steps,
                    &intent.tables,
                    fk_policy,
                )?;
                let inherited = self.merge_fk_inherited_tables(&target_chain, &dependencies)?;
                self.lock_merge_tables(&ends, &merge_owner, &mut merge_locks, &dependencies, &inherited)?;
                // B3 second fix pass: the window from the first run to this one
                // was open to main's DML: validate its keys again. An error here
                // leaves the merge pending, with nothing further changed.
                // A table whose rows landed is done with: its rows are main's now,
                // and main may have changed them since.
                let left = intent.tables_left();
                self.refuse_merged_tables_too_large(&ends, &left)?;
                self.validate_merge_keys(&ends, &intent.steps, &left)?;
                self.validate_merge_fks(&ends, &intent.steps, &intent.tables, &left, fk_policy)?;
                intent
            }
            None => match self.write_merge_intent(&ends, &merge_owner, &mut merge_locks, fk_policy) {
                Ok(intent) => intent,
                Err(e) => {
                    self.release_merge_exclusion(source_id);
                    return Err(e);
                }
            },
        };

        self.merge_failpoint_tick(MergeFailSite::AfterIntent)
            .map_err(|e| Error::branch_merge_interrupted(source_name, target_name, &e))?;

        // Mark the source merged (the resume of a merge that crashed before
        // this has nothing else to do but the same). Nothing else ran yet, so a
        // failure here withdraws the intent: the source stays Active.
        if source_meta.state == super::BranchState::Active {
            let mut merged_meta = source_meta;
            merged_meta.state = super::BranchState::Merged {
                into_branch: target_id,
                at_timestamp: intent.merge_timestamp,
            };
            if let Err(e) = self.write_branch_metadata(&merged_meta) {
                if let Err(undo) = self.delete_branch_merge_intent(source_id) {
                    tracing::warn!(
                        branch = %source_name,
                        error = %undo,
                        "MERGE BRANCH could not mark its source merged, nor withdraw its intent"
                    );
                }
                self.release_merge_exclusion(source_id);
                return Err(e);
            }
        }

        let merged = self.run_branch_merge(&mut intent, &ends);
        // The target level's rows changed below every branch transaction,
        // whatever the outcome: move its write generations, so a statement on the
        // target with a cached overlay reloads it (sprinter 6bc4a4040eb7, B2; B3
        // second fix pass: a stopped merge leaves it readable too).
        if !merge_to_main {
            for table_name in &intent.tables {
                branch_view::bump_write_generation(self.instance_id, target_id, table_name);
            }
        }
        let merged_keys = merged.map_err(|e| Error::branch_merge_interrupted(source_name, target_name, &e))?;
        self.delete_branch_merge_intent(source_id)
            .map_err(|e| Error::branch_merge_interrupted(source_name, target_name, &e))?;
        self.release_merge_exclusion(source_id);
        // Sprinter 6bc4a4040eb7 (B4): nothing can bind it, and nothing will finish
        // it: its keys go, unless a live branch still reads through it. The source
        // was a live child until here: an ABORT could have put it back.
        self.retire_merged_branch(source_id);

        tracing::info!(
            "Merge completed: {} -> {}, {} keys merged",
            source_name,
            target_name,
            merged_keys
        );

        Ok(super::MergeResult {
            merge_timestamp: intent.merge_timestamp,
            merged_keys,
            conflicts: Vec::new(),
            completed: true,
        })
    }

    /// The two ends of a MERGE, validated, and the source's unfinished merge if
    /// it has one (only then may the source be merged already). With
    /// `expected`, they must still be those ids.
    fn merge_ends(
        &self,
        source_name: &str,
        target_name: &str,
        expected: Option<(u64, u64)>,
    ) -> Result<(BranchMetadata, BranchMetadata, Option<MergeIntent>)> {
        let (source, target) = {
            let manager_lock = self.get_or_init_branch_manager()?;
            let manager = manager_lock.read();
            let mgr = manager
                .as_ref()
                .ok_or_else(|| Error::storage("BranchManager not initialized"))?;
            (
                mgr.get_branch_by_name(source_name)?,
                mgr.get_branch_by_name(target_name)?,
            )
        };
        if source_name == "main" || source.parent_id.is_none() {
            return Err(Error::branch_merge(format!(
                "MERGE BRANCH {source_name} INTO {target_name}: main is not a branch that can be merged"
            )));
        }
        if source.branch_id == target.branch_id {
            return Err(Error::branch_merge(format!(
                "MERGE BRANCH {source_name} INTO {target_name}: a branch cannot be merged into itself"
            )));
        }
        let pending = self.branch_merge_intent(source.branch_id)?;
        let source_usable = match source.state {
            super::BranchState::Active => true,
            super::BranchState::Merged { .. } => pending.is_some(),
            super::BranchState::Dropped { .. } => false,
        };
        if !source_usable || expected.is_some_and(|(id, _)| id != source.branch_id) {
            return Err(Error::branch_merge(format!(
                "Source branch '{}' is not active",
                source_name
            )));
        }
        if target.state != super::BranchState::Active || expected.is_some_and(|(_, id)| id != target.branch_id) {
            return Err(Error::branch_merge(format!(
                "Target branch '{}' is not active",
                target_name
            )));
        }
        Ok((source, target, pending))
    }

    /// Spec R5.1: this merge's locks on `tables` (sorted, at the target level) and what
    /// it waits for besides them, within its one budget:
    ///
    /// * the transactions still open on the SOURCE with staged rows. Its running
    ///   statements were drained and a new one is refused, so all that is left of them
    ///   is a COMMIT or a ROLLBACK; each holds the table on the source's level until
    ///   then, and rows committed after the validation would land nowhere;
    /// * into a branch, main's schema statements already past their exclusion check on
    ///   the tables the target inherits (`main_tables`). This takes no lock on main:
    ///   a branch never blocks main's writers.
    ///
    /// A statement in a transaction that wrote one of these tables is refused at once:
    /// the merge lands in commits of its own, so that transaction would write over it,
    /// and it cannot end while its own statement waits.
    fn lock_merge_tables(
        &self,
        ends: &MergeEnds<'_>,
        owner: &super::table_locks::SeparateLockOwner,
        locks: &mut super::table_locks::ExclusiveTableLocks,
        tables: &[String],
        main_tables: &[String],
    ) -> Result<()> {
        let what = format!("MERGE BRANCH {} INTO {}", ends.source_name, ends.target_name);
        let wait = || {
            ends.deadline
                .saturating_duration_since(std::time::Instant::now())
                .min(self.table_locks.timeout())
        };
        let level = if ends.merge_to_main {
            super::table_locks::MAIN_LEVEL
        } else {
            ends.target_id
        };
        let mut sorted: Vec<&str> = tables.iter().map(String::as_str).collect();
        sorted.sort_unstable();
        sorted.dedup();
        for table in sorted {
            if owner.outer_holds(level, table) {
                return Err(Error::table_lock_upgrade_refused(
                    table,
                    "the transaction this MERGE BRANCH runs in has written it",
                ));
            }
            locks.take(level, table, &what, wait())?;
        }
        for table in branch_view::pending_tables_on_level(self.instance_id, ends.source_id) {
            locks.take(ends.source_id, &table, &what, wait())?;
        }
        if !ends.merge_to_main {
            self.table_locks
                .wait_for_exclusive_holders(super::table_locks::MAIN_LEVEL, main_tables, wait())?;
        }
        Ok(())
    }

    /// sprinter 6bc4a4040eb7 (B3 second fix pass, spec R5.1): plan the merge, hold the
    /// DDL it is exposed to, and take its tables' locks, which waits out what is
    /// already running on them; then plan again under the locks, until the plan asks
    /// for nothing that is not held. The FINAL table list is what ends up held. On an
    /// error the caller releases what was registered.
    fn plan_under_exclusion(
        &self,
        ends: &MergeEnds<'_>,
        owner: &super::table_locks::SeparateLockOwner,
        locks: &mut super::table_locks::ExclusiveTableLocks,
        policy: MergeFkPolicy,
    ) -> Result<BranchMergePlan> {
        let level = if ends.merge_to_main {
            MERGE_TARGET_MAIN
        } else {
            ends.target_id
        };
        let mut held_on_level: HashSet<String> = HashSet::new();
        let mut held_on_main: HashSet<String> = HashSet::new();
        for attempt in 0..4 {
            let plan = self.plan_branch_merge(ends)?;
            let dependencies =
                self.merge_fk_dependency_tables(ends.source_id, ends.target_chain, &plan.steps, &plan.tables, policy)?;
            let inherited = self.merge_fk_inherited_tables(ends.target_chain, &dependencies)?;
            let on_level: Vec<String> = dependencies
                .iter()
                .filter(|table| !held_on_level.contains(*table))
                .cloned()
                .collect();
            let on_main: Vec<String> = inherited
                .iter()
                .filter(|table| !held_on_main.contains(*table))
                .cloned()
                .collect();
            if attempt > 0 && on_level.is_empty() && on_main.is_empty() {
                return Ok(plan);
            }
            self.register_merge_exclusion(
                level,
                ends.source_id,
                ends.source_name,
                ends.target_name,
                &on_level,
                true,
            )?;
            self.register_merge_exclusion(
                MERGE_TARGET_MAIN,
                ends.source_id,
                ends.source_name,
                ends.target_name,
                &on_main,
                false,
            )?;
            self.lock_merge_tables(ends, owner, locks, &on_level, &on_main)?;
            held_on_level.extend(on_level);
            held_on_main.extend(on_main);
        }
        Err(Error::branch_merge_ddl_busy(ends.source_name, ends.target_name))
    }

    /// Plan and validate the merge — its tables are held exclusively by then, and the
    /// target's DDL on them is refused — and write its intent. Nothing has changed
    /// before this returns.
    fn write_merge_intent(
        &self,
        ends: &MergeEnds<'_>,
        owner: &super::table_locks::SeparateLockOwner,
        locks: &mut super::table_locks::ExclusiveTableLocks,
        policy: MergeFkPolicy,
    ) -> Result<MergeIntent> {
        let plan = self.plan_under_exclusion(ends, owner, locks, policy)?;
        self.refuse_merged_tables_too_large(ends, &plan.tables)?;
        self.validate_merge_keys(ends, &plan.steps, &plan.tables)?;
        self.validate_merge_fks(ends, &plan.steps, &plan.tables, &plan.tables, policy)?;
        for step in &plan.steps {
            if let MergeAction::AddColumnsOnMain { base_columns, columns } = &step.action {
                self.preflight_merged_columns(&step.table, ends.source_id, base_columns.len(), columns)?;
            }
        }
        let intent = MergeIntent {
            source_id: ends.source_id,
            source_name: ends.source_name.to_string(),
            target_id: ends.target_id,
            target_name: ends.target_name.to_string(),
            merge_to_main: ends.merge_to_main,
            target_chain: ends.target_chain.to_vec(),
            merge_timestamp: self.next_timestamp(),
            steps: plan.steps,
            tables: plan.tables,
            main_tables: plan.main_tables,
            landed: Vec::new(),
        };
        if policy == MergeFkPolicy::Enforced {
            self.put_branch_merge_intent(&intent)?;
        } else {
            self.put_branch_merge_intent_with_fk_policy(&intent, policy)?;
        }
        Ok(intent)
    }

    /// The durable part of a merge: its schema steps, then its rows. Idempotent:
    /// a rerun after a failure or a crash redoes what did not happen and changes
    /// nothing else. Returns the row keys copied.
    fn run_branch_merge(&self, intent: &mut MergeIntent, ends: &MergeEnds<'_>) -> Result<usize> {
        let MergeEnds {
            merge_to_main,
            target_chain,
            ..
        } = *ends;

        // Get all tables from catalog — sprinter 6bc4a4040eb7 (phase B3): main's
        // tables, the tables the merge changes, and (into a branch) the tables
        // the target's chain defines, whose rows live only in overlays.
        let catalog = Catalog::new(self);
        let tables: Vec<String> = {
            let mut set: std::collections::BTreeSet<String> = catalog.list_main_tables()?.into_iter().collect();
            set.extend(intent.tables.iter().cloned());
            if !merge_to_main {
                set.extend(self.branch_tables_in_chain(target_chain)?.into_keys());
            }
            set.into_iter().collect()
        };

        // Step 0 — sprinter 6bc4a4040eb7 (phase B3): carry the source's schema
        // changes into the target BEFORE its rows (a created table must exist
        // to receive them, an added column must be on the target before the
        // branch's wider rows land). Everything was validated before the intent.
        for step in &intent.steps {
            self.merge_failpoint_tick(MergeFailSite::Step)?;
            match &step.action {
                MergeAction::PutOnBranch { record, materialize } => {
                    self.apply_merge_step_to_branch(intent, step, record, materialize.as_deref())?;
                }
                _ => self.apply_merge_step_to_main(&catalog, step, ends.source_id)?,
            }
        }
        // Into main, rows go only to tables main now has: a table the source
        // never defined itself and main does not have (an unmerged ancestor's,
        // with no source rows — the plan refuses one that has some) is not
        // written into a `data:` keyspace no catalog entry describes.
        let main_tables_after: HashSet<String> = if merge_to_main {
            catalog.list_main_tables()?.into_iter().collect()
        } else {
            HashSet::new()
        };
        let receiving: Vec<String> = tables
            .into_iter()
            .filter(|table_name| !merge_to_main || main_tables_after.contains(table_name.as_str()))
            .collect();

        // Into main each table's rows land in an ordinary commit, which raises its
        // watermark and fences the row cache itself; only a branch target's level
        // is written below that (its generations are moved by the caller).
        self.copy_merged_rows(ends, intent, &receiving)
    }

    /// A merge's row phase, on the rows the source itself changed (never its copies).
    /// Returns the row keys it carried.
    ///
    /// Into main, each table lands as one ordinary transaction
    /// (`land_merged_table_on_main`).
    ///
    /// Into a branch, each row goes in one batch with its tombstone, its marker and
    /// its key-index entries (`BranchView::apply_merged_row`), deletions first,
    /// because they free keys the rows after them may take. A level has no versions
    /// and no logical WAL to be consistent with, and the merge runs on it alone, in
    /// its exclusive section. Idempotent: a rerun lands what is already there again.
    fn copy_merged_rows(&self, ends: &MergeEnds<'_>, intent: &mut MergeIntent, tables: &[String]) -> Result<usize> {
        if ends.merge_to_main {
            let mut merged_keys = 0usize;
            for table_name in tables {
                if !intent.landed.contains(table_name) {
                    merged_keys += self.land_merged_table_on_main(ends, intent, table_name)?;
                }
            }
            return Ok(merged_keys);
        }
        let view = BranchView::for_chain(self, ends.target_name, ends.target_chain.to_vec())?;
        let mut merged_keys = 0usize;
        for table_name in tables {
            // B3 fix pass: what the source only COPIED (`bfrz:` — an ADD COLUMN's
            // materialized rows, B4's frozen pre-images) is not a change: the
            // target keeps its own row.
            if self.branch_changed_row_ids(ends.source_id, table_name)?.is_empty() {
                continue;
            }
            let copies = self.branch_frozen_row_ids(ends.source_id, table_name)?;
            let tombstones = self.branch_tombstone_row_ids(ends.source_id, table_name)?;

            // The source's deletions.
            for row_id in &tombstones {
                if copies.contains(row_id) {
                    continue;
                }
                self.merge_failpoint_tick(MergeFailSite::Row)?;
                view.apply_merged_row(table_name, *row_id, None)?;
                self.row_cache.invalidate(table_name, *row_id);
            }

            // The source's images. Within a level a tombstone beats an image (a
            // pre-B2 delete left both), and a copy is no change.
            let branch_prefix = format!("bdata:{}:{}:", ends.source_id, table_name);
            let branch_prefix_bytes = branch_prefix.as_bytes();
            let iter = self.db.iterator(rocksdb::IteratorMode::From(
                branch_prefix_bytes,
                rocksdb::Direction::Forward,
            ));
            for item in iter {
                let (key, value) = item.map_err(|e| Error::storage(format!("Iterator error: {}", e)))?;
                if !key.starts_with(branch_prefix_bytes) {
                    break;
                }
                let Some(row_id) = Self::parse_row_id_after_prefix(&key, branch_prefix_bytes.len()) else {
                    continue;
                };
                if copies.contains(&row_id) || tombstones.contains(&row_id) {
                    continue;
                }
                self.merge_failpoint_tick(MergeFailSite::Row)?;
                // The stored form of a value is a property of the key it lands
                // under, so a row moving between keys is decoded for the key it
                // came FROM and sealed for the key it is going TO — never copied
                // across as bytes. Both directions go through the one rule in `tde`,
                // and both are a no-op with encryption disabled.
                let plain = super::tde::open_ref(self.key_manager.as_deref(), &key, &value)?;
                view.apply_merged_row(table_name, row_id, Some(plain.as_ref()))?;
                // The row cache is keyed (table, row_id) with NO branch dimension:
                // evict any cached entry.
                self.row_cache.invalidate(table_name, row_id);
                merged_keys += 1;
            }
        }
        Ok(merged_keys)
    }

    /// Main's current row `row_id` of `table`, decoded as a scan decodes it.
    fn merged_main_row_image(&self, table: &str, schema: &crate::Schema, row_id: u64) -> Result<Option<Tuple>> {
        match self.get(&Self::build_data_key(table, row_id))? {
            Some(stored) => Ok(Some(self.decode_stored_row(table, schema, row_id, &stored)?)),
            None => Ok(None),
        }
    }

    /// What the source changed in `table`, against main's committed rows. A
    /// deletion of a row main does not have is nothing to do. Decoded, so a column's
    /// stored form on the source plays no part in what lands.
    fn merged_table_rows(&self, source_id: u64, table: &str, schema: &crate::Schema) -> Result<Vec<LandingRow>> {
        let copies = self.branch_frozen_row_ids(source_id, table)?;
        let tombstones = self.branch_tombstone_row_ids(source_id, table)?;
        let mut rows = Vec::new();
        for row_id in &tombstones {
            if copies.contains(row_id) {
                continue;
            }
            if let Some(old) = self.merged_main_row_image(table, schema, *row_id)? {
                rows.push(LandingRow {
                    row_id: *row_id,
                    old: Some(old),
                    new: None,
                });
            }
        }
        let prefix = format!("bdata:{source_id}:{table}:");
        let prefix_bytes = prefix.as_bytes();
        let iter = self
            .db
            .iterator(rocksdb::IteratorMode::From(prefix_bytes, rocksdb::Direction::Forward));
        for item in iter {
            let (key, value) = item.map_err(|e| Error::storage(format!("Iterator error: {}", e)))?;
            if !key.starts_with(prefix_bytes) {
                break;
            }
            let Some(row_id) = Self::parse_row_id_after_prefix(&key, prefix_bytes.len()) else {
                continue;
            };
            if copies.contains(&row_id) || tombstones.contains(&row_id) {
                continue;
            }
            let plain = super::tde::open_ref(self.key_manager.as_deref(), &key, &value)?;
            rows.push(LandingRow {
                row_id,
                old: self.merged_main_row_image(table, schema, row_id)?,
                new: Some(self.decode_stored_row(table, schema, row_id, plain.as_ref())?),
            });
        }
        Ok(rows)
    }

    /// sprinter 6bc4a4040eb7 (B3 fourth fix pass): one table's rows land on main as
    /// ONE ordinary transaction, committed the way a multi-row UPDATE is. The row
    /// phase used to be a write path of its own beside main's, and each property it
    /// lacked was a defect of its own: versions and the version index (AS OF, and any
    /// snapshot read), the logical WAL (a crash replay reverted a finished merge),
    /// the replication wait, the conflict registry, the columnar store. The commit
    /// brings them all, with the row cache, the watermark and the snapshot record, and
    /// a reader or a crash sees the table's merge wholly or not at all.
    ///
    /// Spec R5.1: the merge holds the table exclusively from before its key validation
    /// on, so nothing else stages, moves a key or commits in it meanwhile. The order is
    /// what a transactional UPDATE does, with the keys all at once:
    ///
    /// 1. The transaction first, then the rows read and staged.
    /// 2. Claim all the keys (`claim_merged_table_keys`).
    /// 3. Commit. On any failure the claim goes back, nothing has landed for this
    ///    table, and the intent stays, so a rerun validates again.
    /// 4. Now that the new images are committed, the keys only the old ones held go,
    ///    and the vector indexes follow.
    ///
    /// Which rows landed is written in the same commit (`MergeIntent::landed`).
    fn land_merged_table_on_main(&self, ends: &MergeEnds<'_>, intent: &mut MergeIntent, table: &str) -> Result<usize> {
        let merged = self.branch_changed_row_ids(ends.source_id, table)?;
        let Some(highest_row_id) = merged.iter().copied().max() else {
            return Ok(0);
        };
        self.merge_failpoint_tick(MergeFailSite::Row)?;
        let schema = Catalog::new(self).main_table_schema(table)?;

        let txn = self.begin_transaction()?;
        let rows = self.merged_table_rows(ends.source_id, table, &schema)?;
        if rows.is_empty() {
            return Ok(0);
        }

        if schema_has_columnar_columns(&schema) {
            let images = |existing: bool| -> Vec<(u64, &Tuple)> {
                rows.iter()
                    .filter(|row| row.old.is_some() == existing)
                    .filter_map(|row| row.new.as_ref().map(|new| (row.row_id, new)))
                    .collect()
            };
            self.stage_columnar_rows_grouped_in_transaction(table, &images(true), &schema, &txn, false)?;
            self.stage_columnar_rows_grouped_in_transaction(table, &images(false), &schema, &txn, true)?;
            let deleted: Vec<u64> = rows
                .iter()
                .filter(|row| row.new.is_none())
                .map(|row| row.row_id)
                .collect();
            self.stage_columnar_deletes_grouped_in_transaction(table, &deleted, &schema, &txn)?;
        }
        for row in &rows {
            let key = Self::build_data_key(table, row.row_id);
            match &row.new {
                Some(new) => {
                    let value = bincode::serialize(new)
                        .map_err(|e| Error::storage(format!("Failed to serialize tuple: {}", e)))?;
                    txn.put(key, value)?;
                }
                None => txn.delete(key)?,
            }
        }
        // Row ids come with the rows, so the counter has to pass them: main hands
        // out ids above what landed from now on, also after a crash.
        self.raise_row_counter_to(table, highest_row_id);
        txn.stage_row_counter(
            table,
            self.row_counter_high_water(table)
                .unwrap_or(highest_row_id)
                .max(highest_row_id),
        )?;
        let mut progressed = intent.clone();
        progressed.landed.push(table.to_string());
        self.stage_branch_merge_intent(&progressed, &txn)?;

        // A key moved between rows leaves a committed row without its entry until
        // this commits, as a transactional UPDATE that moves a key does. The commit
        // consumes the transaction, and with it its census slots: this copy of them
        // stays up until the keys are settled, either way, or a COUNT from the index
        // would answer in between with old and new keys both in it.
        txn.note_index_key_removal(table);
        let census = txn.write_census_hold();
        let changes: Vec<MergedRowChange<'_>> = rows
            .iter()
            .map(|row| MergedRowChange {
                row_id: row.row_id,
                old: row.old.as_ref(),
                new: row.new.as_ref(),
            })
            .collect();
        let claim = match self
            .art_index_manager
            .claim_merged_table_keys(table, &schema, &changes)
            .map_err(|e| Error::storage(format!("MERGE BRANCH: claiming the keys of {table}: {e}")))?
        {
            MergedKeysOutcome::Claimed(claim) => claim,
            MergedKeysOutcome::HeldBy {
                wanted_by,
                constraint,
                columns,
            } => {
                let wanted = rows
                    .iter()
                    .find(|row| row.row_id == wanted_by)
                    .and_then(|row| row.new.as_ref());
                let key_text = wanted.map_or_else(
                    || format!("({})", columns.join(", ")),
                    |row| merge_key_text(&schema, &columns, row),
                );
                return Err(Error::branch_merge_key_claimed(
                    ends.source_name,
                    ends.target_name,
                    table,
                    &constraint,
                    &key_text,
                ));
            }
        };
        self.merge_failpoint_tick(MergeFailSite::TableClaimed)?;

        let commit_ts = self.next_commit_timestamp(txn.has_tracked_writes());
        let attempt = super::write_outcome::WriteAttempt::default();
        let mut claim = Some(claim);
        let mut applied = false;
        let mut publication_error = None;
        let result = txn.commit_with_timestamp_settled(commit_ts, &attempt, |_, outcome, _| {
            use super::write_outcome::WriteOutcome;
            match outcome {
                WriteOutcome::NotWritten => {
                    // The native group was refused. Restore every eager key while
                    // this transaction still owns its key/row/census holds.
                    drop(claim.take());
                }
                WriteOutcome::Unknown => {
                    if let Some(claim) = claim.take() {
                        claim.disarm_for_reconciliation();
                    }
                    self.quarantine_generic_indexes(table, "MERGE BRANCH native outcome is unknown");
                }
                WriteOutcome::Applied => {
                    applied = true;
                    // A later fsync/ACK error does not turn these rows into an
                    // abort. Complete all RAM publication before giving up holds.
                    self.bump_schema_generation();
                    if let Some(claim) = claim.take() {
                        if let Err(error) = claim.finish() {
                            publication_error = Some(Error::storage(format!(
                                "MERGE BRANCH: removing the keys {table} no longer holds: {error}"
                            )));
                        }
                    }
                    if self.vector_indexes.table_has_indexes(table) {
                        let actual: Vec<_> = rows.iter().map(|row| (row.row_id, row.new.clone())).collect();
                        if let Err(error) = self.vector_indexes.reconcile_rows_ram_only(table, &schema, &actual) {
                            publication_error.get_or_insert(error);
                        }
                    }
                    if let Some(error) = &publication_error {
                        self.quarantine_generic_indexes(table, &error.to_string());
                    }
                }
            }
        });
        if applied {
            // The progress record belongs to the same native group as the rows.
            *intent = progressed;
        }
        // Preserve an original native/durability error ahead of a derived one.
        result?;
        if let Some(error) = publication_error {
            return Err(Error::applied_publication_failure(error));
        }
        drop(census);
        let _ = self.increment_lsn();
        Ok(rows.len())
    }

    /// The most a merge can stage for one table and still be one write group, which
    /// is never split and above this limit could be neither served nor archived.
    /// Refused (54000) before anything changes. What it counts is what the commit
    /// writes for a row: its `data:` key, its version, its version index, and its
    /// logical WAL record. A merge holds the changed rows of a table in memory.
    fn refuse_merged_tables_too_large(&self, ends: &MergeEnds<'_>, tables: &[String]) -> Result<()> {
        if !ends.merge_to_main {
            return Ok(());
        }
        let limit = branch_view::final_batch_limit();
        for table in tables {
            let copies = self.branch_frozen_row_ids(ends.source_id, table)?;
            let tombstones = self.branch_tombstone_row_ids(ends.source_id, table)?;
            let row_cost = |key_bytes: usize, value_bytes: usize| {
                key_bytes
                    .saturating_mul(4)
                    .saturating_add(value_bytes.saturating_mul(3))
                    .saturating_add(64)
            };
            let mut bytes = row_cost(table.len() + "data::".len() + 20, 0).saturating_mul(tombstones.len());
            let prefix = format!("bdata:{}:{table}:", ends.source_id);
            let prefix_bytes = prefix.as_bytes();
            let iter = self
                .db
                .iterator(rocksdb::IteratorMode::From(prefix_bytes, rocksdb::Direction::Forward));
            for item in iter {
                let (key, value) = item.map_err(|e| Error::storage(format!("Iterator error: {}", e)))?;
                if !key.starts_with(prefix_bytes) {
                    break;
                }
                let own = Self::parse_row_id_after_prefix(&key, prefix_bytes.len())
                    .is_some_and(|row_id| !copies.contains(&row_id) && !tombstones.contains(&row_id));
                if own {
                    bytes = bytes.saturating_add(row_cost(key.len(), value.len()));
                }
            }
            if bytes > limit {
                return Err(Error::branch_merge_table_too_large(
                    ends.source_name,
                    ends.target_name,
                    table,
                    bytes,
                    limit,
                ));
            }
        }
        Ok(())
    }

    /// sprinter 6bc4a4040eb7 (B3 fix pass): finish every MERGE BRANCH an earlier
    /// run left unfinished — rolled forward, never back. Called when the handle
    /// opens, after the indexes are rebuilt; the merge's tables are refused to
    /// DDL from the first moment. A physical standby does nothing: its primary's
    /// completion replicates. One that cannot be finished is logged and stays
    /// pending (a later MERGE statement can still finish it): it never fails the
    /// open. Returns the failures, by source.
    pub fn finish_pending_branch_merges(&self) -> Vec<(String, Error)> {
        // The write condition, not the open mode alone (B3 second fix pass): a
        // fenced primary is opened in a writable mode, and a merge's drop would
        // tear down in-memory indexes before the gate refused its write.
        if !self.engine_may_write() || !self.gate.is_open() {
            return Vec::new();
        }
        let intents = match self.branch_merge_intents() {
            Ok(intents) => intents,
            Err(e) => {
                tracing::error!("Unfinished MERGE BRANCH records could not be read: {}", e);
                return vec![("?".to_string(), e)];
            }
        };
        let mut failures = Vec::new();
        for intent in &intents {
            if let Err(e) = self.register_merge_intent_exclusion(intent) {
                tracing::error!(
                    "Unfinished MERGE BRANCH {} INTO {} cannot hold its tables: {}",
                    intent.source_name,
                    intent.target_name,
                    e
                );
            }
        }
        for intent in intents {
            match self.merge_branch(
                &intent.source_name,
                &intent.target_name,
                super::MergeStrategy::default(),
            ) {
                Ok(_) => tracing::info!(
                    "Finished the interrupted MERGE BRANCH {} INTO {}",
                    intent.source_name,
                    intent.target_name
                ),
                Err(e) => {
                    tracing::error!(
                        "The interrupted MERGE BRANCH {} INTO {} could not be finished: {}; its tables stay \
                         closed to DDL until MERGE BRANCH is run again",
                        intent.source_name,
                        intent.target_name,
                        e
                    );
                    failures.push((intent.source_name, e));
                }
            }
        }
        failures
    }

    /// sprinter 6bc4a4040eb7 (B3 second fix pass): `MERGE BRANCH source ABORT`,
    /// the way out of an unfinished merge that can never finish (its target was
    /// changed by hand, say) and that would otherwise hold its tables and both
    /// ends for good. The source goes back to `Active`, the intent and the
    /// exclusion go. What the merge already did to the target is NOT undone: the
    /// engine keeps no pre-image to undo it with. So this returns (and logs) the
    /// tables that may be partially changed, for the operator to inspect; merging
    /// the source again is validated from scratch. Refused when the source has no
    /// unfinished merge.
    pub fn abort_branch_merge(&self, source_name: &str) -> Result<Vec<String>> {
        let _main_scope = crate::main_statement_scope(self.instance_id);
        let _merge_scope = MergeDdlScope::enter(self.instance_id);
        let read = || -> Result<(BranchMetadata, Option<MergeIntent>)> {
            let source = {
                let manager_lock = self.get_or_init_branch_manager()?;
                let manager = manager_lock.read();
                let mgr = manager
                    .as_ref()
                    .ok_or_else(|| Error::storage("BranchManager not initialized"))?;
                mgr.get_branch_by_name(source_name)?
            };
            let intent = self.branch_merge_intent(source.branch_id)?;
            Ok((source, intent))
        };
        let no_merge = || {
            Error::branch_merge(format!(
                "MERGE BRANCH {source_name} ABORT: branch {source_name} has no unfinished merge"
            ))
        };
        let (source, _) = read()?;
        let _drained = self
            .branch_drains
            .close(source.branch_id, source_name, super::BRANCH_DRAIN_TIMEOUT)?;
        let (mut source, intent) = read()?;
        let intent = intent.ok_or_else(no_merge)?;
        // Active FIRST: a crash between the two leaves an intent on an Active
        // source, which the next open finishes; the other order would leave a
        // Merged source with nothing to finish it, and its rows out of reach.
        source.state = super::BranchState::Active;
        self.write_branch_metadata(&source)?;
        self.delete_branch_merge_intent(source.branch_id)?;
        // Main's indexes follow each row as it lands (B3 third fix pass), so a
        // stopped merge left them matching its rows and there is nothing to rebuild.
        // Only what serves those rows by generation has to notice.
        if intent.merge_to_main {
            self.bump_schema_generation();
        } else {
            for table in &intent.tables {
                branch_view::bump_write_generation(self.instance_id, intent.target_id, table);
            }
        }
        // Last (B3 third fix pass): DDL on these tables stays out until there is
        // nothing left to do to them.
        self.release_merge_exclusion(source.branch_id);
        tracing::warn!(
            "MERGE BRANCH {} INTO {} abandoned; branch {} is active again. These tables of {} may be partially \
             changed: {}",
            source_name,
            intent.target_name,
            source_name,
            intent.target_name,
            intent.tables.join(", ")
        );
        Ok(intent.tables)
    }

    /// Persist `metadata` through the branch manager (cache refresh and
    /// registry-generation bump included) — sprinter 6bc4a4040eb7 (B1).
    fn write_branch_metadata(&self, metadata: &BranchMetadata) -> Result<()> {
        let manager_lock = self.get_or_init_branch_manager()?;
        let manager = manager_lock.read();
        let mgr = manager
            .as_ref()
            .ok_or_else(|| Error::storage("BranchManager not initialized"))?;
        mgr.write_branch_metadata(metadata)
    }

    /// Spec R5.2: what a merge's `ADD COLUMN`s would refuse, asked while the merge
    /// has changed nothing: `base_width` is main's width without them. A NOT NULL
    /// column with no value is judged against what main will hold: the rows the
    /// branch deleted will be gone, and the rows it changed land with their values,
    /// so it is illegal only if main has another row (23502). A volatile default's
    /// rewrite is run into a scratch batch, as the step will run it (54000, 23502,
    /// and any error of the expression; its values are thrown away, so a `nextval`
    /// default consumes them twice).
    fn preflight_merged_columns(
        &self,
        table: &str,
        source_id: u64,
        base_width: usize,
        added: &[super::branch_catalog::BranchAddedColumn],
    ) -> Result<()> {
        use super::row_shape::ColumnFill;
        let fills = added
            .iter()
            .map(|c| ColumnFill::for_default(c.default.as_ref(), &c.column.data_type))
            .collect::<Result<Vec<_>>>()?;
        self.refuse_merged_not_null_over_kept_rows(table, source_id, added.iter().zip(&fills))?;
        if fills.iter().any(|fill| matches!(fill, ColumnFill::PerRow(_))) {
            let plan: Vec<(&str, &crate::DataType, bool, &ColumnFill)> = added
                .iter()
                .zip(&fills)
                .map(|(c, fill)| (c.column.name.as_str(), &c.column.data_type, !c.column.nullable, fill))
                .collect();
            let mut scratch = WriteBatch::default();
            self.stage_added_column_rows(
                table,
                base_width,
                &plan,
                self.config.storage.max_atomic_rewrite_bytes,
                &mut scratch,
            )?;
        }
        Ok(())
    }

    /// A NOT NULL column with no value, of a merge: illegal only if main has a row
    /// the merge will neither delete nor replace (23502).
    fn refuse_merged_not_null_over_kept_rows<'a>(
        &self,
        table: &str,
        source_id: u64,
        columns: impl IntoIterator<
            Item = (
                &'a super::branch_catalog::BranchAddedColumn,
                &'a super::row_shape::ColumnFill,
            ),
        >,
    ) -> Result<()> {
        let unfilled = columns.into_iter().find(|(c, fill)| {
            !c.column.nullable && matches!(fill, super::row_shape::ColumnFill::Constant(crate::Value::Null))
        });
        if let Some((column, _)) = unfilled {
            let carried = self.branch_changed_row_ids(source_id, table)?;
            if self.table_has_rows_other_than(table, &carried)? {
                return Err(Error::add_column_null_on_existing_rows(table, &column.column.name));
            }
        }
        Ok(())
    }

    /// sprinter 6bc4a4040eb7 (phase B3, B3 fix pass): what a merge changes on its
    /// target, decided before anything is written. The source's schema changes
    /// are the records of its OWN catalog level (a frozen copy — phase B4 — is
    /// not a change, and is skipped; so is a tombstone of a table the parent
    /// never had, which leaves the branch's "no such table" in place and nothing
    /// to do on the target). Each must still apply to the target, or the whole
    /// merge is refused (55000), naming the tables:
    ///
    /// * the target's CURRENT definition of the table must be the one the
    ///   source's parent had when the source first changed it
    ///   (`parent_fingerprint`) — otherwise the target changed the table after
    ///   the branch did;
    /// * its CURRENT incarnation must be the one the parent had then
    ///   (`parent_incarnation`) and at the fork (`bmeta:{source}:fork`) —
    ///   otherwise the table was dropped and recreated, even identically, and is
    ///   not the table the branch changed;
    /// * a table the branch only changed ROWS of must have, on the target, the
    ///   definition and the incarnation it had at the fork (B3 second fix pass):
    ///   rows are copied by position, so a `DROP COLUMN` on main would shift them
    ///   and an `ADD COLUMN NOT NULL` would leave them short. Fail closed, no row
    ///   shaping.
    ///
    /// Also refused: rows the source wrote to a table whose definition on the
    /// source comes from an ANCESTOR between the target and the source (that
    /// ancestor's schema change is not the source's to carry; merge the ancestor
    /// first; one already merged into the target's lineage is carried). An open
    /// transaction on the merge's tables is waited for under its table locks (spec
    /// R5.1, 55P03 after the timeout), and the target's other live descendants keep
    /// what they see (B4: the step's record write freezes it into them first).
    fn plan_branch_merge(&self, ends: &MergeEnds<'_>) -> Result<BranchMergePlan> {
        use super::branch_catalog::{BranchTableResolution, BranchTableState};
        let MergeEnds {
            source_name,
            target_name,
            source_id,
            target_id,
            merge_to_main,
            source_chain,
            target_chain,
            ..
        } = *ends;
        let fork = self.branch_fork_record(source_id)?;
        let fork_of = |table: &str| fork.as_ref().and_then(|fork| fork.get(table));
        let records = self.branch_table_records_at(source_id)?;

        let mut steps: Vec<MergeStep> = Vec::new();
        let mut planned: std::collections::BTreeSet<String> = std::collections::BTreeSet::new();
        let mut moved: Vec<String> = Vec::new();
        let mut recreated: Vec<String> = Vec::new();
        let mut gone: Vec<String> = Vec::new();
        let mut changed_since_fork: Vec<String> = Vec::new();
        let mut no_fork_record: Vec<String> = Vec::new();
        for (table, record) in &records {
            if record.frozen {
                continue;
            }
            if matches!(record.state, BranchTableState::Dropped) && record.parent_fingerprint.is_none() {
                continue;
            }
            let target_definition = self.chain_table_definition(target_chain, table)?;
            let before = target_definition.as_ref().map(|(_, fingerprint)| *fingerprint);
            if before != record.parent_fingerprint {
                moved.push(table.clone());
                continue;
            }
            // The incarnation, where both sides know one (a table with none yet
            // is unknown, never different). Absent on either side was settled by
            // the fingerprint.
            let at_fork = fork_of(table);
            if incarnations_differ(
                self.chain_table_incarnation(target_chain, table)?,
                record.parent_incarnation,
            ) || at_fork.is_some_and(|forked| incarnations_differ(forked.incarnation, record.parent_incarnation))
            {
                recreated.push(table.clone());
                continue;
            }
            // Main changed the table between the fork and the branch's first
            // change of it, or dropped it: the branch's earlier rows, if any, were
            // written for the definition at the fork.
            if let Some(forked) = at_fork {
                if Some(forked.fingerprint) != record.parent_fingerprint {
                    match &target_definition {
                        Some((current, _)) => {
                            changed_since_fork.push(describe_definition_change(table, &forked.columns, current));
                        }
                        None => gone.push(table.clone()),
                    }
                    continue;
                }
            }
            // B3 third fix pass: fail closed where nothing says what the rows were
            // written for. See the rows-only loop below.
            if fork.is_none() && !self.branch_changed_row_ids(source_id, table)?.is_empty() {
                no_fork_record.push(table.clone());
                continue;
            }
            let action = if merge_to_main {
                match (&record.state, &target_definition) {
                    (BranchTableState::Dropped, _) => MergeAction::DropOnMain,
                    (BranchTableState::Defined(definition), _) if record.created => MergeAction::CreateOnMain {
                        definition: definition.clone(),
                    },
                    (BranchTableState::Defined(_), Some((current, _))) if !record.added_columns.is_empty() => {
                        MergeAction::AddColumnsOnMain {
                            base_columns: current.schema.columns.iter().map(|c| c.name.clone()).collect(),
                            columns: record.added_columns.clone(),
                        }
                    }
                    (BranchTableState::Defined(_), _) => continue,
                }
            } else {
                self.plan_put_on_branch(target_id, table, record)?
            };
            planned.insert(table.clone());
            steps.push(MergeStep {
                table: table.clone(),
                before,
                action,
            });
        }

        // The tables whose ROWS the source changed with no schema change of its
        // own to carry.
        let mut row_tables: Vec<String> = Vec::new();
        let candidates: std::collections::BTreeSet<String> = {
            let mut set: std::collections::BTreeSet<String> =
                Catalog::new(self).list_main_tables()?.into_iter().collect();
            set.extend(records.keys().cloned());
            if let Some(fork) = &fork {
                set.extend(fork.keys().cloned());
            }
            set.extend(self.branch_tables_in_chain(target_chain)?.into_keys());
            set
        };
        for table in candidates {
            if planned.contains(&table)
                || moved.contains(&table)
                || recreated.contains(&table)
                || gone.contains(&table)
                || no_fork_record.contains(&table)
                || changed_since_fork
                    .iter()
                    .any(|change| change.starts_with(&format!("{table} (")))
                || self.branch_changed_row_ids(source_id, &table)?.is_empty()
            {
                continue;
            }
            // B3 third fix pass: rows are copied by position, so with no record of
            // the definition they were written for, the merge cannot know where
            // they would land. Fail closed. A branch with no fork record was created
            // by an earlier release.
            //
            // Sprinter 6bc4a4040eb7 (B4): a table with no entry in a branch's fork
            // record was created after the fork, and the branch never saw it (the
            // parent's create froze a tombstone into it), so it cannot have changed
            // rows of it unless it created the table itself, which is a record.
            if fork.is_none() {
                no_fork_record.push(table);
                continue;
            }
            match self.chain_table_definition(target_chain, &table)? {
                None => {
                    gone.push(table);
                    continue;
                }
                Some((current, fingerprint)) => {
                    if let Some(forked) = fork_of(&table) {
                        if incarnations_differ(known_incarnation(current.incarnation), forked.incarnation) {
                            recreated.push(table);
                            continue;
                        }
                        if fingerprint != forked.fingerprint {
                            changed_since_fork.push(describe_definition_change(&table, &forked.columns, &current));
                            continue;
                        }
                    }
                }
            }
            row_tables.push(table);
        }

        let mut ancestral: Vec<String> = Vec::new();
        let mut ancestor_lost: Vec<String> = Vec::new();
        for (table, resolution) in self.branch_tables_in_chain(source_chain)? {
            let (level, record) = match &resolution {
                BranchTableResolution::Inherited => continue,
                BranchTableResolution::Defined { level, record, .. }
                | BranchTableResolution::Dropped { level, record, .. } => (*level, record),
            };
            // A copy of a definition is no change an ancestor made.
            if record.frozen {
                continue;
            }
            if level == source_id
                || target_chain.contains(&level)
                || self.branch_changed_row_ids(source_id, &table)?.is_empty()
            {
                continue;
            }
            match self.ancestor_merge_state(level, target_id, target_chain)? {
                AncestorMerge::IntoTheTarget => {}
                AncestorMerge::NotIntoTheTarget => {
                    ancestral.push(format!("{table} (defined by an ancestor branch, id {level})"));
                }
                AncestorMerge::IntoADroppedBranch => ancestor_lost.push(table),
            }
        }
        if !(moved.is_empty()
            && recreated.is_empty()
            && gone.is_empty()
            && changed_since_fork.is_empty()
            && no_fork_record.is_empty()
            && ancestral.is_empty()
            && ancestor_lost.is_empty())
        {
            let mut why = Vec::new();
            if !moved.is_empty() {
                why.push(format!(
                    "the definition of {} changed on {target_name} after branch {source_name} changed it — run the \
                     schema change on {target_name} by hand, or recreate the branch from the current {target_name}",
                    moved.join(", ")
                ));
            }
            if !recreated.is_empty() {
                why.push(format!(
                    "{} was dropped and created again on {target_name} since branch {source_name} forked: it is not \
                     the table the branch changed, even with the same definition — recreate the branch from the \
                     current {target_name}",
                    recreated.join(", ")
                ));
            }
            if !gone.is_empty() {
                why.push(format!(
                    "{} no longer exists on {target_name} under that name (dropped or renamed since branch \
                     {source_name} forked), and the branch changed it — recreate the branch from the current \
                     {target_name}",
                    gone.join(", ")
                ));
            }
            if !changed_since_fork.is_empty() {
                why.push(format!(
                    "the definition on {target_name} changed since branch {source_name} forked, and the branch \
                     changed rows written for the old one: {} — recreate the branch from the current {target_name}",
                    changed_since_fork.join("; ")
                ));
            }
            if !no_fork_record.is_empty() {
                why.push(format!(
                    "branch {source_name}'s fork point is not recorded (it was created by an earlier release), and \
                     it changed rows of {}: nothing records the definitions they were written for — recreate the \
                     branch from the current {target_name}, or copy its rows by hand",
                    no_fork_record.join(", ")
                ));
            }
            if !ancestral.is_empty() {
                why.push(format!(
                    "branch {source_name} wrote rows of {} whose definition it inherits from a branch that is not \
                     merged into {target_name} — merge that branch first",
                    ancestral.join(", ")
                ));
            }
            if !ancestor_lost.is_empty() {
                why.push(format!(
                    "branch {source_name} wrote rows of {} whose definition it inherits from a branch that was \
                     merged into a branch that has since been dropped, so it can never reach {target_name} — copy \
                     those rows by hand, or recreate the branch from the current {target_name}",
                    ancestor_lost.join(", ")
                ));
            }
            return Err(Error::branch_merge_schema_refused(
                source_name,
                target_name,
                &why.join("; "),
            ));
        }

        let mut tables: Vec<String> = steps.iter().map(|step| step.table.clone()).collect();
        tables.extend(row_tables);
        // A drop on main takes partition children with it: they are this merge's
        // tables too, to hold off DDL and to report (B3 third fix pass).
        let dropped_on_main: Vec<String> = steps
            .iter()
            .filter(|step| matches!(step.action, MergeAction::DropOnMain | MergeAction::CreateOnMain { .. }))
            .map(|step| step.table.clone())
            .collect();
        tables.extend(Catalog::new(self).with_partition_descendants(dropped_on_main));
        tables.sort_unstable();
        tables.dedup();
        // A branch target that inherits a table from main is exposed to main's
        // DDL on it (B3 second fix pass): a change there would change what this
        // merge validated, and an identical re-create would pass unseen.
        let mut main_tables = Vec::new();
        if !merge_to_main {
            for table in &tables {
                if matches!(
                    self.resolve_branch_table(target_chain, table)?,
                    BranchTableResolution::Inherited
                ) {
                    main_tables.push(table.clone());
                }
            }
        }
        Ok(BranchMergePlan {
            steps,
            tables,
            main_tables,
        })
    }

    /// The record the target level takes for the source's `record`, computed
    /// once, at plan time: re-applying a step re-writes the same bytes (a
    /// recomputation would double `added_columns` on a rerun). The target keeps
    /// its own `parent_*` when it has an entry (its FIRST change is what its own
    /// merge compares against). `ADD COLUMN`s also rewrite the target's view
    /// under the new definition (`materialize`), so the target keeps every row
    /// it saw, as after its own `ADD COLUMN`.
    fn plan_put_on_branch(
        &self,
        target_id: u64,
        table: &str,
        record: &super::branch_catalog::BranchTableRecord,
    ) -> Result<MergeAction> {
        use super::branch_catalog::{BranchTableRecord, BranchTableState};
        let existing = self.branch_table_record(target_id, table)?;
        let (parent_fingerprint, parent_incarnation) = existing
            .as_ref()
            .map_or((record.parent_fingerprint, record.parent_incarnation), |own| {
                (own.parent_fingerprint, own.parent_incarnation)
            });
        let (created, added_columns) = match &record.state {
            BranchTableState::Dropped => (false, Vec::new()),
            BranchTableState::Defined(_) if record.created => (true, Vec::new()),
            BranchTableState::Defined(_) => match existing.as_deref() {
                Some(own) if own.definition().is_some() => {
                    let mut added = own.added_columns.clone();
                    added.extend(record.added_columns.iter().cloned());
                    (own.created, added)
                }
                _ => (false, record.added_columns.clone()),
            },
        };
        let materialize = (record.definition().is_some() && !record.created && !record.added_columns.is_empty())
            .then(|| record.added_columns.clone());
        Ok(MergeAction::PutOnBranch {
            record: BranchTableRecord {
                state: record.state.clone(),
                isolated: record.isolated,
                frozen: false,
                parent_fingerprint,
                parent_incarnation,
                created,
                added_columns,
            },
            materialize,
        })
    }

    /// sprinter 6bc4a4040eb7 (B3 fix pass, amendment B): MERGE must not produce
    /// a PRIMARY KEY / UNIQUE duplicate on its target. For every row the merge
    /// will put there, probe the target's rules for the key — ignoring the rows
    /// the merge itself deletes or replaces by row id — and refuse 23505 naming
    /// the table, the constraint and the key. Runs before the intent: nothing
    /// has changed, and the source stays Active and mergeable once the
    /// conflicting row is gone. A table the source CREATED replaces the target's
    /// of the name, so only its own rows can collide with each other.
    ///
    /// B3 second fix pass: a key on main can also be held by a row that is not
    /// committed: main's indexes are maintained eagerly, so an open transaction's
    /// INSERT or key-moving UPDATE is in them already. That is a refusal too
    /// (55006, retryable), or the merge would duplicate the key when it commits.
    /// Runs again when a merge resumes.
    ///
    /// A statement that claims the key AFTER this check is met by the row phase:
    /// whichever claims first holds it, and the other is refused, so nothing is
    /// duplicated. What stays open until R5 is in the spec.
    fn merge_fk_definitions(
        &self,
        source_chain: &[u64],
        target_chain: &[u64],
        steps: &[MergeStep],
    ) -> Result<std::collections::BTreeMap<String, super::branch_catalog::BranchTableDefinition>> {
        let mut names: std::collections::BTreeSet<String> =
            Catalog::new(self).list_main_tables()?.into_iter().collect();
        names.extend(self.branch_tables_in_chain(target_chain)?.into_keys());
        names.extend(steps.iter().map(|step| step.table.clone()));
        let mut definitions = std::collections::BTreeMap::new();
        for table in names {
            if let Some((definition, _)) = self.chain_table_definition(target_chain, &table)? {
                definitions.insert(table, definition);
            }
        }
        for step in steps {
            let definition = match &step.action {
                MergeAction::DropOnMain => None,
                MergeAction::CreateOnMain { definition } => Some(definition.clone()),
                MergeAction::PutOnBranch { record, .. } => record.definition().cloned(),
                MergeAction::AddColumnsOnMain { .. } => self
                    .chain_table_definition(source_chain, &step.table)?
                    .map(|(definition, _)| definition),
            };
            match definition {
                Some(definition) => {
                    definitions.insert(step.table.clone(), definition);
                }
                None => {
                    definitions.remove(&step.table);
                }
            }
        }
        Ok(definitions)
    }

    /// Validation dependencies are locked/excluded, but never added to the row
    /// landing list. Recompute under the locks, and again after a crash resume.
    pub(crate) fn merge_fk_dependency_tables(
        &self,
        source: u64,
        target_chain: &[u64],
        steps: &[MergeStep],
        changed: &[String],
        _policy: MergeFkPolicy,
    ) -> Result<Vec<String>> {
        let mut found: std::collections::BTreeSet<String> = changed.iter().cloned().collect();
        // Even Off/Proxy and NOT ENFORCED preserve declarative schema
        // dependencies: row checking is optional, dangling FK definitions are not.
        let source_chain = self.get_branch_chain(source)?;
        let definitions = self.merge_fk_definitions(&source_chain, target_chain, steps)?;
        loop {
            let before = found.len();
            for (child, definition) in &definitions {
                for fk in &definition.constraints.foreign_keys {
                    if found.contains(child) || found.contains(&fk.references_table) {
                        found.insert(child.clone());
                        found.insert(fk.references_table.clone());
                    }
                }
            }
            if found.len() == before {
                return Ok(found.into_iter().collect());
            }
        }
    }

    pub(crate) fn merge_fk_inherited_tables(&self, target_chain: &[u64], tables: &[String]) -> Result<Vec<String>> {
        if target_chain.is_empty() {
            return Ok(Vec::new());
        }
        let mut inherited = Vec::new();
        for table in tables {
            if matches!(
                self.resolve_branch_table(target_chain, table)?,
                super::branch_catalog::BranchTableResolution::Inherited
            ) {
                inherited.push(table.clone());
            }
        }
        Ok(inherited)
    }

    #[allow(clippy::too_many_arguments)]
    fn merge_fk_final_rows(
        &self,
        ends: &MergeEnds<'_>,
        steps: &[MergeStep],
        remaining: &[String],
        table: &str,
        definition: &super::branch_catalog::BranchTableDefinition,
        source: &BranchView<'_>,
        target: &BranchView<'_>,
    ) -> Result<Vec<Tuple>> {
        let pending = remaining.iter().any(|name| name == table);
        let replaced = pending
            && steps.iter().any(|step| {
                step.table == table
                    && match &step.action {
                        MergeAction::CreateOnMain { .. } => true,
                        MergeAction::PutOnBranch { record, .. } => record.created,
                        _ => false,
                    }
            });
        let mut rows = HashMap::new();
        if !replaced {
            if let Some((current, _)) = self.chain_table_definition(ends.target_chain, table)? {
                for mut row in target.scan(None, table, &current.schema)? {
                    let id = row
                        .row_id
                        .ok_or_else(|| Error::internal("MERGE FK target row has no identity"))?;
                    // Branch ADD COLUMN keeps existing FK-column positions;
                    // new constraints are not added by that branch DDL surface.
                    row.values.resize(definition.schema.columns.len(), crate::Value::Null);
                    rows.insert(id, row);
                }
            }
        }
        if pending {
            for id in self.branch_changed_row_ids(ends.source_id, table)? {
                match source.own_entry(None, table, id, definition.schema.columns.len())? {
                    Some(branch_view::LevelEntry::Row(row)) => {
                        rows.insert(id, row);
                    }
                    Some(branch_view::LevelEntry::Tombstone) => {
                        rows.remove(&id);
                    }
                    None => {}
                }
            }
        }
        Ok(rows.into_values().collect())
    }

    /// Validate the final three-way landing, including target children the
    /// source could not see. No mutation or intent precedes strict refusal.
    /// Existing invalid rows admitted by Off/Audit are checked only if the
    /// merge changes that child or breaks a previously valid relationship.
    fn validate_merge_fks(
        &self,
        ends: &MergeEnds<'_>,
        steps: &[MergeStep],
        affected: &[String],
        remaining: &[String],
        policy: MergeFkPolicy,
    ) -> Result<()> {
        use crate::sql::ConstraintEnforcement;
        use crate::Value;
        let _memo = super::OverlayCacheScope::enter();
        let definitions = self.merge_fk_definitions(ends.source_chain, ends.target_chain, steps)?;
        // Check schema dependencies before looking at any child/parent rows:
        // an empty or all-NULL child still owns a real FK definition. These
        // invariants hold in Off/Audit/Proxy/NOT ENFORCED modes as at CREATE.
        for (child, definition) in &definitions {
            let before = self
                .chain_table_definition(ends.target_chain, child)?
                .map(|(definition, _)| definition);
            for fk in &definition.constraints.foreign_keys {
                let fresh = before.as_ref().is_none_or(|before| {
                    !before.constraints.foreign_keys.iter().any(|old| {
                        old.name == fk.name
                            && old.columns == fk.columns
                            && old.references_table == fk.references_table
                            && old.references_columns == fk.references_columns
                    })
                });
                if !fresh && !affected.contains(child) && !affected.contains(&fk.references_table) {
                    continue;
                }
                let invalid = |why: &str| {
                    Error::constraint_violation(format!(
                        "Foreign key constraint '{}' has an invalid final MERGE schema: {why}",
                        fk.name
                    ))
                };
                if fk.columns.is_empty() || fk.columns.len() != fk.references_columns.len() {
                    return Err(invalid("child and parent key arity differ"));
                }
                let mut child_columns = fk
                    .columns
                    .iter()
                    .map(|column| {
                        definition
                            .schema
                            .get_column_index(column)
                            .ok_or_else(|| invalid("child column is absent"))
                    })
                    .collect::<Result<Vec<_>>>()?;
                child_columns.sort_unstable();
                if child_columns
                    .iter()
                    .zip(child_columns.iter().skip(1))
                    .any(|(first, second)| first == second)
                {
                    return Err(invalid("child column is repeated"));
                }
                let parent = definitions
                    .get(&fk.references_table)
                    .ok_or_else(|| invalid("referenced parent table is absent"))?;
                let mut referenced = fk
                    .references_columns
                    .iter()
                    .map(|column| {
                        parent
                            .schema
                            .get_column_index(column)
                            .ok_or_else(|| invalid("referenced parent column is absent"))
                    })
                    .collect::<Result<Vec<_>>>()?;
                referenced.sort_unstable();
                if referenced
                    .iter()
                    .zip(referenced.iter().skip(1))
                    .any(|(first, second)| first == second)
                {
                    return Err(invalid("referenced parent column is repeated"));
                }
                let unique = parent.unique_rules.iter().any(|rule| {
                    if rule.columns.len() != referenced.len() {
                        return false;
                    }
                    let mut columns = rule
                        .columns
                        .iter()
                        .map(|column| parent.schema.get_column_index(column))
                        .collect::<Option<Vec<_>>>();
                    if let Some(columns) = &mut columns {
                        columns.sort_unstable();
                    }
                    columns.as_ref() == Some(&referenced)
                });
                if !unique {
                    return Err(invalid(
                        "referenced columns have no qualifying PRIMARY KEY or UNIQUE key",
                    ));
                }
            }
        }
        if policy == MergeFkPolicy::Bypass {
            return Ok(());
        }
        let source = BranchView::for_chain(self, ends.source_name, ends.source_chain.to_vec())?;
        let target = BranchView::for_chain(
            self,
            ends.target_name,
            if ends.merge_to_main {
                vec![ends.target_id]
            } else {
                ends.target_chain.to_vec()
            },
        )?;
        let mut final_rows: HashMap<String, Vec<Tuple>> = HashMap::new();
        let mut before_keys: HashMap<(String, Vec<String>), HashSet<Vec<Value>>> = HashMap::new();
        let mut final_keys: HashMap<(String, Vec<String>), HashSet<Vec<Value>>> = HashMap::new();
        let values = |schema: &crate::Schema, row: &Tuple, columns: &[String]| -> Result<Vec<Value>> {
            columns
                .iter()
                .map(|column| {
                    schema
                        .get_column_index(column)
                        .and_then(|index| row.values.get(index))
                        .cloned()
                        .ok_or_else(|| {
                            Error::constraint_violation(format!(
                                "Foreign key column '{column}' is absent from final MERGE schema"
                            ))
                        })
                })
                .collect()
        };
        for (child, definition) in &definitions {
            let changed_ids = if remaining.contains(child) {
                self.branch_changed_row_ids(ends.source_id, child)?
            } else {
                HashSet::new()
            };
            let before_child = self
                .chain_table_definition(ends.target_chain, child)?
                .map(|(definition, _)| definition);
            for fk in &definition.constraints.foreign_keys {
                if fk.enforcement == ConstraintEnforcement::NotEnforced {
                    continue;
                }
                let fresh = before_child.as_ref().is_none_or(|before| {
                    !before.constraints.foreign_keys.iter().any(|old| {
                        old.name == fk.name
                            && old.columns == fk.columns
                            && old.references_table == fk.references_table
                            && old.references_columns == fk.references_columns
                    })
                });
                if !fresh && changed_ids.is_empty() && !affected.contains(&fk.references_table) {
                    continue;
                }
                if !final_rows.contains_key(child) {
                    final_rows.insert(
                        child.clone(),
                        self.merge_fk_final_rows(ends, steps, remaining, child, definition, &source, &target)?,
                    );
                }
                let set_key = (fk.references_table.clone(), fk.references_columns.clone());
                if !final_keys.contains_key(&set_key) {
                    let mut keys = HashSet::new();
                    if let Some(parent) = definitions.get(&fk.references_table) {
                        if !final_rows.contains_key(&fk.references_table) {
                            final_rows.insert(
                                fk.references_table.clone(),
                                self.merge_fk_final_rows(
                                    ends,
                                    steps,
                                    remaining,
                                    &fk.references_table,
                                    parent,
                                    &source,
                                    &target,
                                )?,
                            );
                        }
                        let rows = final_rows
                            .get(&fk.references_table)
                            .ok_or_else(|| Error::internal("FK MERGE parent row set is absent after preparation"))?;
                        for row in rows {
                            keys.insert(values(&parent.schema, row, &fk.references_columns)?);
                        }
                    }
                    final_keys.insert(set_key.clone(), keys);
                }
                let before_parent = self
                    .chain_table_definition(ends.target_chain, &fk.references_table)?
                    .map(|(definition, _)| definition);
                if !before_keys.contains_key(&set_key) {
                    let mut keys = HashSet::new();
                    if let Some(parent) = &before_parent {
                        for row in target.scan(None, &fk.references_table, &parent.schema)? {
                            keys.insert(values(&parent.schema, &row, &fk.references_columns)?);
                        }
                    }
                    before_keys.insert(set_key.clone(), keys);
                }
                let child_rows = final_rows
                    .get(child)
                    .ok_or_else(|| Error::internal("FK MERGE child row set is absent after preparation"))?;
                let prior_parent_keys = before_keys
                    .get(&set_key)
                    .ok_or_else(|| Error::internal("FK MERGE prior parent keys are absent after preparation"))?;
                let merged_parent_keys = final_keys
                    .get(&set_key)
                    .ok_or_else(|| Error::internal("FK MERGE final parent keys are absent after preparation"))?;
                for row in child_rows {
                    let child_values = values(&definition.schema, row, &fk.columns)?;
                    if child_values.iter().any(|value| matches!(value, Value::Null)) {
                        continue;
                    }
                    let parent_schema = definitions
                        .get(&fk.references_table)
                        .map(|parent| &parent.schema)
                        .or_else(|| before_parent.as_ref().map(|parent| &parent.schema));
                    let wanted = parent_schema.map_or_else(
                        || child_values.clone(),
                        |schema| {
                            crate::EmbeddedDatabase::coerce_fk_probe_values(
                                schema,
                                &fk.references_columns,
                                &child_values,
                            )
                        },
                    );
                    let touched = fresh || row.row_id.is_some_and(|id| changed_ids.contains(&id));
                    if !touched && !prior_parent_keys.contains(&wanted) {
                        continue;
                    }
                    if merged_parent_keys.contains(&wanted) {
                        continue;
                    }
                    if policy == MergeFkPolicy::Audit || fk.enforcement == ConstraintEnforcement::LockFree {
                        crate::EmbeddedDatabase::record_fk_violation_with(
                            self,
                            if policy == MergeFkPolicy::Audit {
                                crate::FkValidationMode::Audit
                            } else {
                                crate::FkValidationMode::Enforced
                            },
                            fk,
                            &child_values,
                        )?;
                    } else {
                        return Err(Error::constraint_violation(format!("Foreign key constraint '{}' violated by MERGE BRANCH {} INTO {}: child '{}' references a missing parent '{}'",
                            fk.name, ends.source_name, ends.target_name, child, fk.references_table)));
                    }
                }
            }
        }
        Ok(())
    }

    fn validate_merge_keys(&self, ends: &MergeEnds<'_>, steps: &[MergeStep], tables: &[String]) -> Result<()> {
        // Main's committed rows by key, when an open main transaction makes its
        // index unreliable, are scanned once for the whole validation.
        let _memo = super::OverlayCacheScope::enter();
        let source_view = BranchView::for_chain(self, ends.source_name, ends.source_chain.to_vec())?;
        let target_view = if ends.merge_to_main {
            BranchView::for_chain(self, "main", vec![ends.target_id])?
        } else {
            BranchView::for_chain(self, ends.target_name, ends.target_chain.to_vec())?
        };
        for table in tables {
            let step = steps.iter().find(|step| &step.table == table);
            let created = match step.map(|step| &step.action) {
                Some(MergeAction::DropOnMain) => continue,
                Some(MergeAction::CreateOnMain { .. }) => true,
                Some(MergeAction::PutOnBranch { record, .. }) => {
                    if record.definition().is_none() {
                        continue;
                    }
                    record.created
                }
                _ => false,
            };
            let Some((source_definition, _)) = self.chain_table_definition(ends.source_chain, table)? else {
                continue;
            };
            let (rules, target_schema) = if created {
                let rules: Vec<crate::storage::EnforcedUniqueIndex> = source_definition
                    .unique_rules
                    .iter()
                    .map(super::branch_catalog::BranchUniqueRule::to_enforced)
                    .collect();
                (rules, None)
            } else {
                let Some((target_definition, _)) = self.chain_table_definition(ends.target_chain, table)? else {
                    // Main has no such table: the rows go nowhere (the row phase
                    // writes no `data:` a catalog entry does not describe).
                    continue;
                };
                (target_view.unique_rules(table)?, Some(target_definition.schema))
            };
            if rules.is_empty() {
                continue;
            }
            let merged = self.branch_changed_row_ids(ends.source_id, table)?;
            let mut skip = self.branch_frozen_row_ids(ends.source_id, table)?;
            skip.extend(self.branch_tombstone_row_ids(ends.source_id, table)?);
            let mut seen: std::collections::HashMap<(usize, Vec<u8>), u64> = std::collections::HashMap::new();
            source_view.for_each_own_changed_image(
                table,
                source_definition.schema.columns.len(),
                &skip,
                |row_id, tuple| {
                    for (position, rule) in rules.iter().enumerate() {
                        let Some(key) = branch_view::rule_key(&source_definition.schema, rule, &tuple.values) else {
                            continue;
                        };
                        let encoded = crate::storage::ArtIndexManager::encode_key(&key);
                        let twice = seen
                            .insert((position, encoded), row_id)
                            .is_some_and(|other| other != row_id);
                        let held = match &target_schema {
                            Some(schema) => target_view
                                .rows_with_key(None, table, schema, &rule.columns, &key)?
                                .iter()
                                .any(|holder| holder.row_id.is_some_and(|holder| !merged.contains(&holder))),
                            None => false,
                        };
                        let key_text = merge_key_text(&source_definition.schema, &rule.columns, &tuple);
                        if twice || held {
                            return Err(Error::branch_merge_duplicate_key(
                                ends.source_name,
                                ends.target_name,
                                table,
                                if rule.is_primary_key { "PRIMARY KEY" } else { "UNIQUE" },
                                &rule.label,
                                &key_text,
                            ));
                        }
                        if let (true, Some(schema)) = (ends.merge_to_main, &target_schema) {
                            if target_view.main_key_held_by_an_uncommitted_row(
                                table,
                                schema,
                                &rule.columns,
                                &key,
                                &merged,
                            )? {
                                return Err(Error::branch_merge_key_claimed(
                                    ends.source_name,
                                    ends.target_name,
                                    table,
                                    &rule.label,
                                    &key_text,
                                ));
                            }
                        }
                    }
                    Ok(())
                },
            )?;
        }
        Ok(())
    }

    /// sprinter 6bc4a4040eb7 (B3 fix pass): one schema step of a merge into
    /// main — EVERY main-side catalog write of a merge is here — through main's
    /// own catalog funnels (the merge runs under a main scope). Idempotent: what
    /// main holds now decides whether the step has run, partly run or not run. A
    /// state no run of the step can produce refuses; the target's DDL is held
    /// off these tables, so that takes an operator's hand after a crash.
    fn apply_merge_step_to_main(&self, catalog: &Catalog<'_>, step: &MergeStep, source_id: u64) -> Result<()> {
        let table = step.table.as_str();
        let now = self.main_table_definition(table)?;
        let now_fingerprint = now.as_ref().map(|(_, fingerprint)| *fingerprint);
        let now_incarnation = catalog.main_table_incarnation(table)?;
        let unchanged = now_fingerprint == step.before;
        let changed = || {
            Error::query_execution(format!(
                "table {table} changed on main while the merge was unfinished; it cannot be finished"
            ))
        };
        match &step.action {
            MergeAction::DropOnMain => {
                if now.is_none() {
                    return Ok(());
                }
                if !unchanged {
                    return Err(changed());
                }
                self.drop_main_table_for_merge(catalog, table)?;
            }
            MergeAction::CreateOnMain { definition } => {
                // The definition's own incarnation on main: this create already
                // ran, perhaps only partly. Main's old table of the name goes
                // first. The columns of the definition under another id: a WAL
                // replay at open re-created it, so this create ran too, and the
                // table takes the id it would have had.
                let ran = now_incarnation == Some(definition.incarnation) && now.is_some();
                if !ran {
                    let empty = crate::sql::TableConstraints::default();
                    match &now {
                        None => self.create_merged_table(catalog, table, definition)?,
                        Some(_) if unchanged => {
                            self.drop_main_table_for_merge(catalog, table)?;
                            self.create_merged_table(catalog, table, definition)?;
                        }
                        Some((current, _))
                            if super::branch_catalog::definition_fingerprint(&current.schema, &empty, &[])?
                                == super::branch_catalog::definition_fingerprint(&definition.schema, &empty, &[])? =>
                        {
                            catalog.set_table_incarnation(table, definition.incarnation)?;
                        }
                        Some(_) => return Err(changed()),
                    }
                }
                let constraints = &definition.constraints;
                if !constraints.foreign_keys.is_empty()
                    || !constraints.check_constraints.is_empty()
                    || !constraints.unique_constraints.is_empty()
                {
                    catalog.save_table_constraints(table, constraints)?;
                    catalog.register_unique_constraint_indexes(table, constraints)?;
                }
                if !definition.identity_columns.is_empty() {
                    catalog.register_identity_columns(table, &definition.identity_columns)?;
                }
                // sprinter 6bc4a4040eb7 (B3 fourth fix pass): main can write this
                // table from now on, also while the merge is pending, so its counter
                // passes the source's row ids before any row lands, durably, on a
                // rerun too. A row main committed under id 1 would be overwritten by
                // the source's row 1 when it landed. The open-time re-seeding ran
                // before the table existed, or before a rerun.
                if let Some(highest) = self.branch_changed_row_ids(source_id, table)?.into_iter().max() {
                    self.raise_row_counter_to(table, highest);
                    self.flush_row_counter(table)?;
                }
            }
            MergeAction::AddColumnsOnMain { base_columns, columns } => {
                // Main's columns must be the base plus a prefix of the added
                // ones; the rest is what is left to add.
                let (mut schema, _) = now
                    .map(|(definition, fingerprint)| (definition.schema, fingerprint))
                    .ok_or_else(changed)?;
                let names: Vec<&str> = schema.columns.iter().map(|c| c.name.as_str()).collect();
                let added_already = names.len().checked_sub(base_columns.len()).ok_or_else(changed)?;
                let expected = base_columns
                    .iter()
                    .map(String::as_str)
                    .chain(columns.iter().take(added_already).map(|c| c.column.name.as_str()));
                if added_already > columns.len()
                    || !names.iter().copied().eq(expected)
                    || (added_already == 0 && !unchanged)
                {
                    return Err(changed());
                }
                // Spec R5.2: the schema and the columns' missing values in ONE
                // group, as main's own `ADD COLUMN`, so main's rows read right at
                // once and a rerun finds the step done. Only a volatile default
                // rewrites rows, in that same group. The rows the source changed
                // land by their own commit, as wide as its definition.
                if added_already < columns.len() {
                    let old_width = schema.columns.len();
                    let added: Vec<&super::branch_catalog::BranchAddedColumn> =
                        columns.iter().skip(added_already).collect();
                    let fills = added
                        .iter()
                        .map(|c| super::row_shape::ColumnFill::for_default(c.default.as_ref(), &c.column.data_type))
                        .collect::<Result<Vec<_>>>()?;
                    schema.columns.extend(added.iter().map(|c| c.column.clone()));
                    let plan: Vec<(&str, &crate::DataType, bool, &super::row_shape::ColumnFill)> = added
                        .iter()
                        .zip(&fills)
                        .map(|(c, fill)| (c.column.name.as_str(), &c.column.data_type, !c.column.nullable, fill))
                        .collect();
                    // NOT NULL is judged against what main holds once the merge's
                    // own rows have landed, as the preflight judged it: a row main
                    // gained since then is refused here, and the merge stops
                    // pending, not accepted with NULL in the column.
                    self.refuse_merged_not_null_over_kept_rows(table, source_id, added.iter().copied().zip(&fills))?;
                    catalog.add_columns(table, &schema, old_width, &plan, false)?;
                }
                self.merge_failpoint_tick(MergeFailSite::Step)?;
            }
            MergeAction::PutOnBranch { .. } => {
                return Err(Error::internal("a branch step of a merge reached main's apply"));
            }
        }
        Ok(())
    }

    /// Main's table goes, as main's own `DROP TABLE` takes it
    /// (`ddl::drop_table_and_partition_children` + `on_table_dropped`, B3 second
    /// fix pass): its partition children with it, its pushdown structures, and its
    /// triggers out of the live registry.
    fn drop_main_table_for_merge(&self, catalog: &Catalog<'_>, table: &str) -> Result<()> {
        let children = catalog.drop_table_taking_partition_children(table)?;
        self.predicate_pushdown().remove_table(table);
        self.deregister_dropped_table_triggers(table);
        for child in children {
            if catalog.main_table_exists(&child)? {
                self.drop_main_table_for_merge(catalog, &child)?;
            }
        }
        Ok(())
    }

    /// Main's table of a definition a branch created: the definition's columns,
    /// under the definition's incarnation id.
    fn create_merged_table(
        &self,
        catalog: &Catalog<'_>,
        table: &str,
        definition: &super::branch_catalog::BranchTableDefinition,
    ) -> Result<()> {
        let mut schema = definition.schema.clone();
        for column in &mut schema.columns {
            column.source_table = None;
            column.source_table_name = None;
        }
        catalog.create_table_with_incarnation(table, schema, definition.incarnation)
    }

    /// One schema step of a merge into a branch: the target level takes the
    /// plan's record (a drop or a re-creation clears the level's own rows of the
    /// table; `ADD COLUMN`s rewrite what the level sees under it). The record is
    /// the last write, so holding those exact bytes means the step ran.
    fn apply_merge_step_to_branch(
        &self,
        intent: &MergeIntent,
        step: &MergeStep,
        record: &super::branch_catalog::BranchTableRecord,
        materialize: Option<&[super::branch_catalog::BranchAddedColumn]>,
    ) -> Result<()> {
        let table = step.table.as_str();
        let stored = self.get(&super::branch_catalog::branch_table_key(intent.target_id, table))?;
        if stored.is_some_and(|bytes| record.encode().is_ok_and(|wanted| wanted == bytes)) {
            return Ok(());
        }
        // Sprinter 6bc4a4040eb7 (B4): the target's other live descendants keep what
        // they see. The source has its own record of the table, so it is not one. The
        // merge holds the table's lock on the target (spec R5.1), which is what the
        // census of open writers here used to stand in for.
        self.freeze_table_into_children(intent.target_id, table)?;
        let now = self.chain_table_definition(&intent.target_chain, table)?;
        if now.as_ref().map(|(_, fingerprint)| *fingerprint) != step.before {
            return Err(Error::query_execution(format!(
                "table {table} changed on branch {} while the merge was unfinished; it cannot be finished",
                intent.target_name
            )));
        }
        match (materialize, now) {
            (Some(columns), Some((current, _))) => {
                let fills = columns
                    .iter()
                    .map(|c| {
                        super::row_shape::ColumnFill::for_default(c.default.as_ref(), &c.column.data_type)
                            .map(|fill| (fill, &c.column.data_type))
                    })
                    .collect::<Result<Vec<_>>>()?;
                let view = BranchView::for_chain(self, intent.target_name.as_str(), intent.target_chain.clone())?;
                view.materialize_with(table, &current.schema, record, &|| {
                    fills
                        .iter()
                        .map(|(fill, data_type)| fill.next_value(data_type))
                        .collect()
                })?;
            }
            _ => {
                let clear_rows = record.definition().is_none() || record.created;
                self.put_branch_table_record(
                    intent.target_id,
                    table,
                    record,
                    rocksdb::WriteBatch::default(),
                    clear_rows,
                )?;
            }
        }
        Ok(())
    }

    /// Begin a transaction on a specific branch
    ///
    /// Creates a branch-aware transaction that implements copy-on-write semantics.
    /// Reads will check the current branch first, then walk the parent chain.
    pub fn begin_branch_transaction(&self, branch_name: &str) -> Result<BranchTransaction> {
        let manager_lock = self.get_or_init_branch_manager()?;
        let manager = manager_lock.read();
        let mgr = manager
            .as_ref()
            .ok_or_else(|| Error::storage("BranchManager not initialized"))?;

        // Get branch metadata
        let branch = mgr.get_branch_by_name(branch_name)?;

        // Build parent chain for reads
        let parent_chain = mgr.build_parent_chain(branch.branch_id)?;

        // Get snapshot ID
        let snapshot_id = self.next_timestamp();

        // Create branch transaction
        BranchTransaction::new(
            Arc::clone(&self.db),
            Arc::clone(&self.gate),
            branch.branch_id,
            branch,
            parent_chain,
            snapshot_id,
            Arc::clone(&self.snapshot_manager),
            self.key_manager.clone(),
        )
    }

    /// Get branch metadata by name (alias for get_branch)
    pub fn get_branch_metadata(&self, name: &str) -> Result<BranchMetadata> {
        self.get_branch(name)
    }

    /// Get branch name by ID
    pub fn get_branch_name(&self, branch_id: BranchId) -> Option<String> {
        let manager_lock = self.get_or_init_branch_manager().ok()?;
        let manager = manager_lock.read();
        let mgr = manager.as_ref()?;
        mgr.get_branch_name(branch_id)
    }

    /// `USE BRANCH branch_name` for the session whose statement runs on the
    /// calling thread — sprinter 6bc4a4040eb7 (phase B1).
    ///
    /// Binds THAT session only ([`Self::bind_session_branch`]); every other
    /// connection keeps its own branch. `main` returns the session to main;
    /// an unknown, dropped or merged branch is refused (3D000). A caller with
    /// no session installed has nothing to bind and is refused rather than
    /// silently moving some shared slot — there is none any more.
    pub fn use_branch(&self, branch_name: &str) -> Result<()> {
        let state = crate::session_scoped_state_tls().ok_or_else(|| {
            Error::query_execution(
                "USE BRANCH needs a session to bind the branch to; run it through a connection or an \
                 EmbeddedDatabase entry point",
            )
        })?;
        self.bind_session_branch(&state, branch_name)?;
        tracing::info!("Session switched to branch '{}'", branch_name);
        Ok(())
    }

    /// Get current timestamp (read-only)
    pub fn current_timestamp(&self) -> u64 {
        *self.timestamp.read()
    }

