    fn replication_primary() -> StorageEngine {
        let mut config = Config::in_memory();
        config.storage.wal_enabled = true;
        let engine = StorageEngine::open_in_memory(&config).expect("open primary");
        engine
            .catalog()
            .create_table("t", replication_test_schema())
            .expect("create table");
        for id in 1..=3 {
            engine
                .insert_tuple(
                    "t",
                    Tuple {
                        values: vec![Value::Int4(id)],
                        row_id: None,
                        branch_id: None,
                    },
                )
                .expect("insert");
        }
        engine
    }

    /// Catch-up must say "everything you lack", "you are ahead" or "history gone".
    /// It must never answer an unservable position with an empty, successful batch.
    #[test]
    fn logical_wal_catchup_distinguishes_entries_ahead_and_pruned() {
        let primary = replication_primary();
        let latest = primary.wal_lsn().expect("lsn");
        assert!(latest > 0);

        let first = primary.logical_wal_catchup(0).expect("catch-up");
        assert!(
            matches!(first, LogicalCatchup::Entries { .. }),
            "expected entries, got {first:?}"
        );
        if let LogicalCatchup::Entries { latest: l, entries } = first {
            assert_eq!(l, latest);
            assert!(!entries.is_empty(), "a fresh standby must receive the retained history");
            let lsns: Vec<u64> = entries.iter().map(|e| e.lsn).collect();
            let mut sorted = lsns.clone();
            sorted.sort_unstable();
            sorted.dedup();
            assert_eq!(lsns, sorted, "oldest first, no duplicates");
        }
        assert!(matches!(
            primary.logical_wal_catchup(latest).expect("current"),
            LogicalCatchup::Entries { entries, .. } if entries.is_empty()
        ));
        assert!(matches!(
            primary.logical_wal_catchup(latest + 10).expect("ahead"),
            LogicalCatchup::StandbyAhead { .. }
        ));

        // Checkpointing removes history: a standby below it can no longer be served.
        primary
            .wal
            .as_ref()
            .expect("wal")
            .read()
            .truncate_to_checkpoint(latest)
            .expect("checkpoint");
        assert!(matches!(
            primary.logical_wal_catchup(0).expect("pruned"),
            LogicalCatchup::Pruned { .. }
        ));
        assert!(matches!(
            primary.logical_wal_catchup(latest).expect("at checkpoint"),
            LogicalCatchup::Entries { entries, .. } if entries.is_empty()
        ));
    }

    /// The standby's cursor advances with every applied entry, is readable from
    /// durable state, and a re-delivered insert does not silently succeed twice.
    #[test]
    fn replication_cursor_tracks_applied_entries() {
        let primary = replication_primary();
        let entries = primary.wal_entries_for_tests().expect("entries");
        let last = entries.last().expect("entries").lsn;

        let mut config = Config::in_memory();
        config.storage.wal_enabled = true;
        let standby = StorageEngine::open_in_memory(&config).expect("open standby");
        assert_eq!(standby.replication_applied_lsn().expect("cursor"), 0);
        for entry in entries {
            standby
                .apply_replicated_operation_at(entry.lsn, entry.operation)
                .expect("apply");
        }
        assert_eq!(standby.replication_applied_lsn().expect("cursor"), last);
        assert_eq!(standby.scan_table("t").expect("scan").len(), 3);
    }

    #[test]
    fn test_wal_logging_with_table_names() {
        // Test that WAL entries now contain actual table names instead of "unknown"
        let mut config = Config::in_memory();
        config.storage.wal_enabled = true;

        let engine = StorageEngine::open_in_memory(&config).expect("Failed to open in-memory storage");

        // Create a test table
        let schema = Schema {
            columns: vec![
                Column {
                    name: "id".to_string(),
                    data_type: DataType::Int4,
                    nullable: false,
                    primary_key: true,
                    source_table: None,
                    source_table_name: None,
                    default_expr: None,
                    unique: false,
                    storage_mode: crate::ColumnStorageMode::Default,
                },
                Column {
                    name: "name".to_string(),
                    data_type: DataType::Text,
                    nullable: false,
                    primary_key: false,
                    source_table: None,
                    source_table_name: None,
                    default_expr: None,
                    unique: false,
                    storage_mode: crate::ColumnStorageMode::Default,
                },
            ],
        };

        let catalog = engine.catalog();
        catalog
            .create_table("test_users", schema)
            .expect("Failed to create table");

        // Insert a tuple (which calls put internally)
        let tuple = Tuple {
            values: vec![Value::Int4(1), Value::String("Alice".to_string())],
            row_id: None,
            branch_id: None,
        };
        engine
            .insert_tuple("test_users", tuple)
            .expect("Failed to insert tuple");

        // Verify WAL was created and has entries
        assert!(engine.is_wal_enabled());
        let lsn = engine.wal_lsn().expect("WAL should have LSN");
        assert!(lsn > 0, "WAL should have at least one entry");

        // Replay WAL to check entries
        if let Some(wal) = &engine.wal {
            let wal = wal.read();
            let entries = wal.replay().expect("Failed to replay WAL");

            // Find insert operation
            let has_insert_with_table = entries.iter().any(|entry| {
                if let crate::storage::WalOperation::Insert { table, .. } = &entry.operation {
                    table == "test_users"
                } else {
                    false
                }
            });

            assert!(
                has_insert_with_table,
                "WAL should contain insert operation for test_users table"
            );
        }
    }

